window.EXAM_STUDIES = window.EXAM_STUDIES || {}; window.EXAM_STUDIES[2] = {"1":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(25 נקודות) הוכיחו את משפט קנטור (משפט 5.48): פונקציה ממשית <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> שהיא רציפה בקטע סגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span> רציפה בו במידה שווה.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">פונקציה בלי קפיצות על קטע סגור (שכולל את שני הקצוות שלו) לא יכולה להפוך לתלולה יותר ויותר בלי סוף — אותו מרווח אופקי מתאים לכולם.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: פונקציה בלי קפיצות על קטע סגור (שכולל את שני הקצוות שלו) לא יכולה להפוך לתלולה יותר ויותר בלי סוף — אותו מרווח אופקי מתאים לכולם.</p>\n<p><strong>תמונה בראש</strong>: דמיינו סרט מדידה באורך <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> שמצוייר עליו גרף חלק ורציף משמאל לימין. בקטע פתוח (כמו <span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{x}\\)</span>)</span> הגרף יכול להזדקף כמו צוק אינסופי ליד הקצה החסר, כך שמרחק אופקי קטן נותן קפיצה ענקית. אבל כששני הקצוות נמצאים בפנים והפונקציה רציפה גם בהם, אין לה איפה להסתתר וליצור &quot;צוק פתאומי&quot;: יש מהירות שינוי מוגבלת לכל הקטע.</p>\n<p><strong>עם מספרים</strong>: על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x^2\\)</span> רציפה במידה שווה: לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>,</span> אפשר לבחור <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\frac{\\varepsilon}{2}\\)</span> שעובד בכל מקום <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span></span> (כי המרחק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x^2-y^2|=|x+y|\\cdot|x-y|\\le 2|x-y|\\)</span>).</span> לעומת זאת על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span>,</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{1}{x}\\)</span> רציפה בכל נקודה, אבל ליד הקצה החסר <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> היא מזנקת: <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0.01, y=0.005\\)</span></span> ההפרש האופקי הוא <span class=\"math math-inline\" dir=\"ltr\">\\(0.005\\)</span> בלבד והקפיצה היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(200-100=100\\)</span>.</span></p>\n<p><strong>רציפות במידה שווה</strong> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> פירושה שלכל גובה שגיאה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>,</span> קיים מרווח אופקי <em>אחיד</em> <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> כך שכל שתי נקודות בקטע שהמרחק ביניהן קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span></span> נותנות ערכים במרחק קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span></span> — <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span></span> תלוי רק <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span></span> ולא במיקום הנקודות.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בדקו בהדגמה איך בונים זוג סדרות שמתקרבות זו לזו בזמן שערכי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> נשארים מרוחקים לפחות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0\\)</span>,</span> ואיך בולצאנו-ויירשטראס והרציפות סוגרים את הפער לסתירה.</p>\n<figure class=\"demo\" id=\"demo-uniform\" data-demo=\"uniform\"><noscript><p>ההמחשה האינטראקטיבית דורשת JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: מתחילים בשלילה","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: מתחילים בשלילה</p><div class=\"callout-body\"><p>הניחו בשלילה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> אינה רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></span> רשמו את השלילה של הגדרה 5.46: קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0&gt;0\\)</span> שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> קיים זוג נקודות שנכשל.</p></div></div>"},{"title":"רמז 2: מציבים $\\delta=\\frac{1}{n}$ ומחלצים תת-סדרה","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: מציבים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\frac{1}{n}\\)</span> ומחלצים תת-סדרה</p><div class=\"callout-body\"><p>הציבו <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\frac{1}{n}\\)</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> כדי לבנות שתי סדרות <span class=\"math math-inline\" dir=\"ltr\">\\(x_n,y_n\\in[a,b]\\)</span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(|x_n-y_n|&lt;\\frac{1}{n}\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x_n)-f(y_n)|\\ge\\varepsilon_0\\)</span>.</span></span> לאיזו סדרה מפעילים את משפט בולצאנו-ויירשטראס (3.32)?</p></div></div>"},{"title":"רמז 3: עוברים לאותם אינדקסים גם ב-$y$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: עוברים לאותם אינדקסים גם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(y\\)</span></span></p><div class=\"callout-body\"><p>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_{n_k}\\to c\\in[a,b]\\)</span>,</span> מדוע <em>אותה</em> תת-סדרה של אינדקסים <span class=\"math math-inline\" dir=\"ltr\">\\((y_{n_k})\\)</span> מתכנסת גם היא לאותו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>?</span> איך אפיון היינה לרציפות (טענה 5.4) מביא את הסתירה?</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נניח בשלילה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> אינה רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> ומתוך השלילה נבנה לכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\frac{1}{n}\\)</span> זוג נקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x_n,y_n\\in[a,b]\\)</span> שקרובות כדי <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n}\\)</span> אך תמונותיהן במרחק לפחות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0\\)</span>.</span> בעזרת בולצאנו-ויירשטראס נמצא תת-סדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x_{n_k}\\to c\\in[a,b]\\)</span>,</span> נוכיח שגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y_{n_k}\\to c\\)</span>,</span> ונשתמש ברציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span></span> כדי לקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x_{n_k})-f(y_{n_k})\\to 0\\)</span>,</span> בסתירה לכך שההפרש הוא תמיד לפחות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: הנחת השלילה ובניית הסדרות.</strong> נניח בשלילה כי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה רציפה במידה שווה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> לפי שלילת הגדרה 5.46, קיים מספר <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> קיימות נקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[a,b]\\)</span> המקיימות:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|x-y|&lt;\\delta \\quad\\text{וגם}\\quad |f(x)-f(y)|\\ge\\varepsilon_0.\\]</div>\n<p>בפרט, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\frac{1}{n}&gt;0\\)</span> ונקבל נקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x_n,y_n\\in[a,b]\\)</span> שעבורן מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|x_n-y_n|&lt;\\frac{1}{n} \\quad\\text{וגם}\\quad |f(x_n)-f(y_n)|\\ge\\varepsilon_0.\\]</div>\n<p><em>למה?</em> אם שום <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span> לא מספיק עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0\\)</span>,</span> אפשר להציב מרווחים קטנים יותר ויותר <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{1},\\frac{1}{2},\\frac{1}{3},\\dots\\)</span>),</span> ובכל שלב לצלם זוג נקודות שנכשל.</p>\n<p><strong>שלב 2: חילוץ תת-סדרה מתכנסת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></span></strong> כל איברי הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> שייכים לקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span> כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(a\\le x_n\\le b\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> חסומה (הגדרה 2.15). לפי משפט בולצאנו-ויירשטראס (משפט 3.32), יש לה תת-סדרה מתכנסת <span class=\"math math-inline\" dir=\"ltr\">\\((x_{n_k})\\)</span> המתכנסת לגבול ממשי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{k\\to\\infty}x_{n_k}=c.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\le x_{n_k}\\le b\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\)</span>,</span> ומעבר לגבול שומר אי-שוויון חלש (משפט 2.31), מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le c\\le b\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span>.</span></p>\n<p><strong>שלב 3: התכנסות התת-סדרה התאומה <span class=\"math math-inline\" dir=\"ltr\">\\((y_{n_k})\\)</span> לאותו גבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>.</span></strong> מאחר שסדרת האינדקסים <span class=\"math math-inline\" dir=\"ltr\">\\((n_k)\\)</span> עולה ממש של מספרים טבעיים, מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(n_k\\ge k\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\in\\mathbb N\\)</span>.</span> לפיכך משלב 1:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[0\\le |y_{n_k}-x_{n_k}|&lt;\\frac{1}{n_k}\\le\\frac{1}{k}.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{k\\to\\infty}\\frac{1}{k}=0\\)</span></span> (טענה 2.10), משפט הסנדוויץ׳ (משפט 2.32) נותן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{k\\to\\infty}(y_{n_k}-x_{n_k})=0\\)</span>.</span> לכן מאריתמטיקה של גבולות (משפט 2.28):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{k\\to\\infty}y_{n_k}=\\lim_{k\\to\\infty}\\big(x_{n_k}+(y_{n_k}-x_{n_k})\\big)=c+0=c.\\]</div>\n<p><em>למה?</em> אנחנו שומרים <em>בדיוק על אותם אינדקסים</em> <span class=\"math math-inline\" dir=\"ltr\">\\(n_k\\)</span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y\\)</span>,</span> ולא מפעילים בולצאנו-ויירשטראס שוב בנפרד — אחרת הנקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(y\\)</span></span> לא היו באות בזוגות! מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(y_{n_k}\\)</span></span> צמודה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(x_{n_k}\\)</span></span> עד כדי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n_k}\\to 0\\)</span>,</span> היא נמשכת בעצמה אל אותו גבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>.</span></p>\n<p><strong>שלב 4: שימוש ברציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span></span> והגעה לסתירה.</strong> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> היא רציפה גם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span></span> (הגדרות 5.26 ו-5.16). מאחר ששתי הסדרות <span class=\"math math-inline\" dir=\"ltr\">\\((x_{n_k}),(y_{n_k})\\subset[a,b]\\)</span> מתכנסות <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>,</span></span> אפיון היינה לרציפות (טענה 5.4, המסתמכת על משפט 4.30) נותן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{k\\to\\infty}f(x_{n_k})=f(c) \\quad\\text{וגם}\\quad \\lim_{k\\to\\infty}f(y_{n_k})=f(c).\\]</div>\n<p>מאריתמטיקה של גבולות (משפט 2.28) נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{k\\to\\infty}\\big(f(x_{n_k})-f(y_{n_k})\\big)=f(c)-f(c)=0.\\]</div>\n<p>מכאן שלפי הגדרת הגבול (הגדרה 2.9, עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\varepsilon_0&gt;0\\)</span>)</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(K\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(k&gt;K\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x_{n_k})-f(y_{n_k})|&lt;\\varepsilon_0\\)</span>.</span> אולם לפי שלב 1 מתקיים לכל <span class=\"math math-inline\" dir=\"ltr\">\\(k\\in\\mathbb N\\)</span> <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x_{n_k})-f(y_{n_k})|\\ge\\varepsilon_0\\)</span>.</span></span> סתירה!</p>\n<p><strong>שלב 5: מסקנה.</strong> ההנחה בשלילה שגויה, ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></span></p></div></div>","steps":["<p><strong>שלב 1: הנחת השלילה ובניית הסדרות.</strong> נניח בשלילה כי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה רציפה במידה שווה בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span> לפי שלילת הגדרה 5.46, קיים מספר <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> קיימות נקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[a,b]\\)</span> המקיימות:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|x-y|&lt;\\delta \\quad\\text{וגם}\\quad |f(x)-f(y)|\\ge\\varepsilon_0.\\]</div>\n<p>בפרט, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\frac{1}{n}&gt;0\\)</span> ונקבל נקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x_n,y_n\\in[a,b]\\)</span> שעבורן מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|x_n-y_n|&lt;\\frac{1}{n} \\quad\\text{וגם}\\quad |f(x_n)-f(y_n)|\\ge\\varepsilon_0.\\]</div>\n<p><em>למה?</em> אם שום <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span> לא מספיק עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0\\)</span>,</span> אפשר להציב מרווחים קטנים יותר ויותר <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{1},\\frac{1}{2},\\frac{1}{3},\\dots\\)</span>),</span> ובכל שלב לצלם זוג נקודות שנכשל.</p>","<p><strong>שלב 2: חילוץ תת-סדרה מתכנסת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></span></strong> כל איברי הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> שייכים לקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span> כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(a\\le x_n\\le b\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> חסומה (הגדרה 2.15). לפי משפט בולצאנו-ויירשטראס (משפט 3.32), יש לה תת-סדרה מתכנסת <span class=\"math math-inline\" dir=\"ltr\">\\((x_{n_k})\\)</span> המתכנסת לגבול ממשי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{k\\to\\infty}x_{n_k}=c.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\le x_{n_k}\\le b\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\)</span>,</span> ומעבר לגבול שומר אי-שוויון חלש (משפט 2.31), מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a\\le c\\le b\\)</span>,</span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span>.</span></p>","<p><strong>שלב 3: התכנסות התת-סדרה התאומה <span class=\"math math-inline\" dir=\"ltr\">\\((y_{n_k})\\)</span> לאותו גבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>.</span></strong> מאחר שסדרת האינדקסים <span class=\"math math-inline\" dir=\"ltr\">\\((n_k)\\)</span> עולה ממש של מספרים טבעיים, מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(n_k\\ge k\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k\\in\\mathbb N\\)</span>.</span> לפיכך משלב 1:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[0\\le |y_{n_k}-x_{n_k}|&lt;\\frac{1}{n_k}\\le\\frac{1}{k}.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{k\\to\\infty}\\frac{1}{k}=0\\)</span></span> (טענה 2.10), משפט הסנדוויץ׳ (משפט 2.32) נותן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{k\\to\\infty}(y_{n_k}-x_{n_k})=0\\)</span>.</span> לכן מאריתמטיקה של גבולות (משפט 2.28):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{k\\to\\infty}y_{n_k}=\\lim_{k\\to\\infty}\\big(x_{n_k}+(y_{n_k}-x_{n_k})\\big)=c+0=c.\\]</div>\n<p><em>למה?</em> אנחנו שומרים <em>בדיוק על אותם אינדקסים</em> <span class=\"math math-inline\" dir=\"ltr\">\\(n_k\\)</span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y\\)</span>,</span> ולא מפעילים בולצאנו-ויירשטראס שוב בנפרד — אחרת הנקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(y\\)</span></span> לא היו באות בזוגות! מכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(y_{n_k}\\)</span></span> צמודה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(x_{n_k}\\)</span></span> עד כדי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n_k}\\to 0\\)</span>,</span> היא נמשכת בעצמה אל אותו גבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>.</span></p>","<p><strong>שלב 4: שימוש ברציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span></span> והגעה לסתירה.</strong> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> היא רציפה גם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span></span> (הגדרות 5.26 ו-5.16). מאחר ששתי הסדרות <span class=\"math math-inline\" dir=\"ltr\">\\((x_{n_k}),(y_{n_k})\\subset[a,b]\\)</span> מתכנסות <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>,</span></span> אפיון היינה לרציפות (טענה 5.4, המסתמכת על משפט 4.30) נותן:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{k\\to\\infty}f(x_{n_k})=f(c) \\quad\\text{וגם}\\quad \\lim_{k\\to\\infty}f(y_{n_k})=f(c).\\]</div>\n<p>מאריתמטיקה של גבולות (משפט 2.28) נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{k\\to\\infty}\\big(f(x_{n_k})-f(y_{n_k})\\big)=f(c)-f(c)=0.\\]</div>\n<p>מכאן שלפי הגדרת הגבול (הגדרה 2.9, עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\varepsilon_0&gt;0\\)</span>)</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(K\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(k&gt;K\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x_{n_k})-f(y_{n_k})|&lt;\\varepsilon_0\\)</span>.</span> אולם לפי שלב 1 מתקיים לכל <span class=\"math math-inline\" dir=\"ltr\">\\(k\\in\\mathbb N\\)</span> <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x_{n_k})-f(y_{n_k})|\\ge\\varepsilon_0\\)</span>.</span></span> סתירה!</p>","<p><strong>שלב 5: מסקנה.</strong> ההנחה בשלילה שגויה, ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>.</span></span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>להפעיל את בולצאנו-ויירשטראס פעם אחת על <span class=\"math math-inline\" dir=\"ltr\">\\((x_n)\\)</span> ופעם שנייה בנפרד על <span class=\"math math-inline\" dir=\"ltr\">\\((y_n)\\)</span> עם תת-סדרה אחרת: חייבים להשתמש <em>באותה</em> סדרת אינדקסים <span class=\"math math-inline\" dir=\"ltr\">\\(n_k\\)</span> כדי לשמור על הקשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x_{n_k})-f(y_{n_k})|\\ge\\varepsilon_0\\)</span>.</span></li><li>לשכוח לנמק למה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in[a,b]\\)</span> (בזכות סגירות הקטע ומשפט 2.31), שבלי זה אי אפשר להפעיל את רציפות <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span>.</span></span></li></ul></div></div>"}],"similar":"<p><strong>שאלות דומות</strong>: <a href=\"#/exams/40/q1\">2026א · מועד 83, שאלה 1</a> · <a href=\"#/exams/41/q1\">2026א · מועד 88, שאלה 1</a></p>","mc":null},"2":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(25 נקודות) <strong>א.</strong> (10 נק׳) הוכיחו את משפט 2.12: אם סדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> מתכנסת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\)</span></span> וגם <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(L_2\\)</span></span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_1=L_2\\)</span>.</span></p>\n<p><strong>ב.</strong> (15 נק׳) תהי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> פונקציה גזירה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)&gt;x^2\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>.</span> הוכיחו <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> אינה רציפה במידה שווה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span> הדרכה: הוכיחו תחילה שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in(0,\\infty)\\)</span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;y\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(y)-f(x)&gt;x^2(y-x)\\)</span>.</span></p></div></div>","parts":[{"label":"א","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">סדרה לא יכולה להתקרב בו-זמנית לשני מספרים שונים, כי אי אפשר להיות קרוב מאוד גם <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\)</span></span> וגם <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(L_2\\)</span></span> בלי ליפול בין הכיסאות.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: סדרה לא יכולה להתקרב בו-זמנית לשני מספרים שונים, כי אי אפשר להיות קרוב מאוד גם <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\)</span></span> וגם <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(L_2\\)</span></span> בלי ליפול בין הכיסאות.</p>\n<p><strong>תמונה בראש</strong>: נניח ששני שערים נפרדים עומדים במרחק שני מטרים זה מזה. אם נשרטט סביב כל שער עיגול ברדיוס חצי מטר, העיגולים לא נוגעים זה בזה. כדור לא יכול להימצא בו-זמנית בתוך שני העיגולים — ואם מדובר בחצי מהמרחק בין <span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_2\\)</span>,</span></span> שתי סביבות-<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span> זרות לחלוטין.</p>\n<p><strong>עם מספרים</strong>: אילו סדרה התכנסה גם <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> וגם <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span>,</span></span> המרחק ביניהם הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span>,</span> אז נבחר חצי מרחק: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\frac{|1-3|}{2}=1\\)</span>.</span> סביבת-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> של <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> היא <span class=\"math math-inline\" dir=\"ltr\">\\((0,2)\\)</span> וסביבת-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> של <span class=\"math math-inline\" dir=\"ltr\">\\(3\\)</span> היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((2,4)\\)</span>.</span> החל מאינדקס מסוים כל איברי הסדרה חייבים להיות גם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,2)\\)</span></span> וגם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((2,4)\\)</span></span> — וזה בלתי אפשרי כי אין שום מספר שנמצא בשני הקטעים!</p>\n<p><strong>סביבת-<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span></strong> של נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span> היא הקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((L-\\varepsilon,L+\\varepsilon)\\)</span>,</span> כלומר כל המספרים במרחק קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span></span> <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\)</span>.</span></span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול פס הסביבה <span class=\"math math-inline\" dir=\"ltr\">\\((L_1-r, L_1+r)\\)</span> סביב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_1=1\\)</span>,</span> ובאדום הפס סביב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_2=3\\)</span>.</span> הזיזו את הסליידר <span class=\"math math-inline\" dir=\"ltr\">\\(r\\)</span> (המייצג את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>):</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(r\\le 1=\\frac{|L_2-L_1|}{2}\\)</span> שני הפסים זרים לחלוטין, כך שגבול כפול הוא בלתי אפשרי.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:0,&quot;xmax&quot;:10,&quot;ymin&quot;:-0.5,&quot;ymax&quot;:4.5}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;r&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;r=0.8&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.2,&quot;max&quot;:1.4,&quot;step&quot;:0.1}},{&quot;id&quot;:&quot;L1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;L1u&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1+r&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;L1d&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1-r&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;L2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=3&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;L2u&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=3+r&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;L2d&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=3-r&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: איך בוחרים $\\varepsilon$ קונקרטי","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: איך בוחרים <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span> קונקרטי</p><div class=\"callout-body\"><p>הניחו בשלילה כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\ne L_2\\)</span>.</span> בחרו <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span> כחצי מהמרחק בין שני הגבולות: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\frac{|L_1-L_2|}{2}\\)</span>.</span></p></div></div>"},{"title":"רמז 2: מחכים ששני ההגדרות יתקיימו יחד","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: מחכים ששני ההגדרות יתקיימו יחד</p><div class=\"callout-body\"><p>מהתכנסות <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\to L_1\\)</span> יש <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(N_1\\)</span>,</span> ומהתכנסות <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\to L_2\\)</span> יש <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(N_2\\)</span>.</span> איזה אינדקס <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> מבטיח שגם הקרבה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\)</span></span> וגם הקרבה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(L_2\\)</span></span> מתקיימות יחד?</p></div></div>"},{"title":"רמז 3: סגירה עם אי-שוויון המשולש","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: סגירה עם אי-שוויון המשולש</p><div class=\"callout-body\"><p>הפעילו את אי-שוויון המשולש (טענה 1.49) על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|L_1-L_2|=|(L_1-a_n)+(a_n-L_2)|\\)</span>.</span> מה מקבלים?</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נניח בשלילה כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\ne L_2\\)</span>,</span> נגדיר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=\\frac{|L_1-L_2|}{2}&gt;0\\)</span>,</span> ונפעיל עבורו את הגדרת הגבול פעמיים (<span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\)</span></span> <span class=\"nobr\">ול-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_2\\)</span>).</span></span> מעבר למקסימום משני האינדקסים נקבל בעזרת אי-שוויון המשולש <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|L_1-L_2|&lt;|L_1-L_2|\\)</span>,</span></span> וזו סתירה.</p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: הנחת השלילה ובחירת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>.</span></strong> נניח בשלילה כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\ne L_2\\)</span>.</span> אז המרחק ביניהם חיובי, ונגדיר:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\varepsilon=\\frac{|L_1-L_2|}{2}&gt;0.\\]</div>\n<p><strong>שלב 2: הפעלת הגדרת הגבול על <span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\)</span> ועל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_2\\)</span>.</span></strong></p>\n<ul><li>כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=L_1\\)</span>,</span></span> לפי הגדרה 2.9 עבור <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span> שנקבע, קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N_1\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|a_n-L_1|&lt;\\varepsilon\\)</span>.</span></li><li>כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=L_2\\)</span>,</span></span> לפי הגדרה 2.9 עבור אותו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>,</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N_2\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_2\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|a_n-L_2|&lt;\\varepsilon\\)</span>.</span></li></ul>\n<p><em>למה?</em> כל אחת מההתכנסויות מתחילה מהמקום שלה, אבל אנחנו צריכים איבר אחד שמקיים את שתי הקרבות במקביל.</p>\n<p><strong>שלב 3: בחירת אינדקס משותף והגעה לסתירה.</strong> נבחר מספר טבעי <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;\\max(N_1,N_2)\\)</span> (למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n=N_1+N_2+1\\)</span>).</span> אז גם <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_1\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_2\\)</span>,</span> ולכן שני האי-שוויונות מתקיימים עבורו. מאי-שוויון המשולש (טענה 1.49):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|L_1-L_2|=|(L_1-a_n)+(a_n-L_2)|\\le |L_1-a_n|+|a_n-L_2|=|a_n-L_1|+|a_n-L_2|&lt;\\varepsilon+\\varepsilon=2\\varepsilon=|L_1-L_2|.\\]</div>\n<p>קיבלנו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|L_1-L_2|&lt;|L_1-L_2|\\)</span>,</span> וזו סתירה (אף מספר אינו קטן ממש מעצמו).</p>\n<p><strong>שלב 4: מסקנה.</strong> ההנחה <span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\ne L_2\\)</span> שגויה, ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_1=L_2\\)</span>.</span></p></div></div>","steps":["<p><strong>שלב 1: הנחת השלילה ובחירת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>.</span></strong> נניח בשלילה כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\ne L_2\\)</span>.</span> אז המרחק ביניהם חיובי, ונגדיר:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\varepsilon=\\frac{|L_1-L_2|}{2}&gt;0.\\]</div>","<p><strong>שלב 2: הפעלת הגדרת הגבול על <span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\)</span> ועל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_2\\)</span>.</span></strong></p>\n<ul><li>כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=L_1\\)</span>,</span></span> לפי הגדרה 2.9 עבור <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span> שנקבע, קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N_1\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|a_n-L_1|&lt;\\varepsilon\\)</span>.</span></li><li>כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=L_2\\)</span>,</span></span> לפי הגדרה 2.9 עבור אותו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>,</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(N_2\\in\\mathbb N\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_2\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|a_n-L_2|&lt;\\varepsilon\\)</span>.</span></li></ul>\n<p><em>למה?</em> כל אחת מההתכנסויות מתחילה מהמקום שלה, אבל אנחנו צריכים איבר אחד שמקיים את שתי הקרבות במקביל.</p>","<p><strong>שלב 3: בחירת אינדקס משותף והגעה לסתירה.</strong> נבחר מספר טבעי <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;\\max(N_1,N_2)\\)</span> (למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n=N_1+N_2+1\\)</span>).</span> אז גם <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_1\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;N_2\\)</span>,</span> ולכן שני האי-שוויונות מתקיימים עבורו. מאי-שוויון המשולש (טענה 1.49):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|L_1-L_2|=|(L_1-a_n)+(a_n-L_2)|\\le |L_1-a_n|+|a_n-L_2|=|a_n-L_1|+|a_n-L_2|&lt;\\varepsilon+\\varepsilon=2\\varepsilon=|L_1-L_2|.\\]</div>\n<p>קיבלנו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|L_1-L_2|&lt;|L_1-L_2|\\)</span>,</span> וזו סתירה (אף מספר אינו קטן ממש מעצמו).</p>","<p><strong>שלב 4: מסקנה.</strong> ההנחה <span class=\"math math-inline\" dir=\"ltr\">\\(L_1\\ne L_2\\)</span> שגויה, ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L_1=L_2\\)</span>.</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לשכוח שבהגדרה צריך לקחת <span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;\\max(N_1,N_2)\\)</span> כדי להפעיל את שני תנאי הגבול באותו אינדקס <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>.</span></li><li>לבחור <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=|L_1-L_2|\\)</span> במקום חצי מהמרחק <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{|L_1-L_2|}{2}\\)</span> — אז אי-שוויון המשולש נותן <span class=\"math math-inline\" dir=\"ltr\">\\(|L_1-L_2|&lt;2|L_1-L_2|\\)</span> ואינו מוביל לסתירה!</li></ul></div></div>"},{"label":"ב","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">פונקציה שהשיפוע שלה גדול <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span></span> הולכת ונהיית תלולה יותר בלי גבול ימינה, ולכן אפילו צעדים קטנים ושואפים לאפס יוצרים קפיצות גובה ענקיות — אין <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span> אחיד שיכול לעצור אותה.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: פונקציה שהשיפוע שלה גדול <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span></span> הולכת ונהיית תלולה יותר בלי גבול ימינה, ולכן אפילו צעדים קטנים ושואפים לאפס יוצרים קפיצות גובה ענקיות — אין <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span> אחיד שיכול לעצור אותה.</p>\n<p><strong>תמונה בראש</strong>: תחשבו על רכבת הרים שהמסילה שלה נעשית תלולה יותר ככל שמתקדמים ימינה (<span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=10\\)</span></span> השיפוע כבר מעל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(100\\)</span>,</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1000\\)</span></span> מעל מיליון). לא משנה כמה תצמצמו את אורך הצעד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span>,</span> אם תלכו מספיק רחוק ימינה (למשל לנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(x=n\\)</span> גדולה מספיק), אפילו צעד פצפון באורך <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n}&lt;\\delta\\)</span> יקפיץ את הגובה ביותר <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n^2\\cdot\\frac{1}{n}=n\\ge 1\\)</span>.</span></span></p>\n<p><strong>עם מספרים</strong>: ניקח לדוגמה את <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac{x^3}{3}+x\\)</span> (אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=x^2+1&gt;x^2\\)</span>).</span> אם מישהו מציע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=0.1\\)</span>,</span> נבחר <span class=\"math math-inline\" dir=\"ltr\">\\(n=20\\)</span> (אז הצעד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{20}=0.05&lt;0.1\\)</span>).</span> המעבר <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(x=20\\)</span></span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(y=20.05\\)</span></span> נותן קפיצה של בערך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(20^2\\cdot 0.05=20\\)</span>,</span> הרבה יותר <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=1\\)</span>.</span></span></p>\n<p><strong>משפט לגראנז׳</strong> מקשר בין הקפיצה בגובה <span class=\"math math-inline\" dir=\"ltr\">\\(f(y)-f(x)\\)</span> לבין המרחק <span class=\"math math-inline\" dir=\"ltr\">\\(y-x\\)</span> והשיפוע באמצע: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(y)-f(x)=f'(c)(y-x)\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול דוגמה לפונקציה המקיימת את התנאי: <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac{x^3}{3}+x\\)</span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=x^2+1&gt;x^2\\)</span>).</span> הזיזו את הסליידר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>:</span> המרחק האופקי בין הנקודות <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(n+\\frac{1}{n}\\)</span></span> (שני הקווים האפורים) הולך וקטן, אבל הקפיצה האנכית ביניהן (בין הכתומה לאדומה) הולכת וגדלה מעל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>.</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.2,&quot;xmax&quot;:5.5,&quot;ymin&quot;:-1,&quot;ymax&quot;:45}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;n&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;n=2&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:1,&quot;max&quot;:4,&quot;step&quot;:1}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\frac{x^{3}}{3}+x&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;p1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n,f(n))&quot;,&quot;color&quot;:&quot;#fa7e19&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;p2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n+\\\\frac{1}{n},f(n+\\\\frac{1}{n}))&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;lx&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=n&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;ly&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=n+\\\\frac{1}{n}&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: מתחילים לפי ההדרכה","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: מתחילים לפי ההדרכה</p><div class=\"callout-body\"><p>בחרו שני מספרים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;x&lt;y\\)</span>.</span> מדוע מותר להפעיל את משפט לגראנז׳ (8.6) על הקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([x,y]\\)</span>?</span></p></div></div>"},{"title":"רמז 2: שימוש בהנחה על $f'(c)$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: שימוש בהנחה על <span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)\\)</span></p><div class=\"callout-body\"><p>משפט לגראנז׳ נותן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(x,y)\\)</span>.</span> אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;x&lt;c\\)</span>,</span> איך <span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)\\)</span> מושווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span>?</span></span></p></div></div>"},{"title":"רמז 3: הפרכת רציפות במ\"ש ישירות מההגדרה","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: הפרכת רציפות במ&quot;ש ישירות מההגדרה</p><div class=\"callout-body\"><p>קחו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0=1\\)</span>.</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span>,</span> מצאו טבעי <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n}&lt;\\delta\\)</span>,</span></span> והציבו <span class=\"math math-inline\" dir=\"ltr\">\\(x=n\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(y=n+\\frac{1}{n}\\)</span></span> באי-שוויון מההדרכה!</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>תחילה נוכיח בעזרת משפט לגראנז׳ את אי-השוויון שבהדרכה לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;x&lt;y\\)</span>.</span> לאחר מכן נפריך את הגדרת הרציפות במידה שווה (הגדרה 5.46) על <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0=1\\)</span>:</span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> נבחר טבעי <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> שעבורו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n}&lt;\\delta\\)</span>,</span> ניקח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=n, y=n+\\frac{1}{n}\\)</span>,</span> ונראה כי <span class=\"math math-inline\" dir=\"ltr\">\\(|y-x|&lt;\\delta\\)</span> אך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(y)-f(x)&gt;n\\ge 1\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: הוכחת ההדרכה בעזרת משפט לגראנז׳.</strong> יהיו <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in(0,\\infty)\\)</span> המקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;y\\)</span>.</span> הקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([x,y]\\)</span> מוכל <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span></span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([x,y]\\)</span>.</span> ממשפט 7.9 (גזירות גוררת רציפות) נובע כי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([x,y]\\)</span>,</span></span> ובפרט גזירה בקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((x,y)\\)</span>.</span> לפי משפט לגראנז׳ (משפט 8.6) על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([x,y]\\)</span>,</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(x,y)\\)</span> כך ש:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(y)-f(x)=f'(c)(y-x).\\]</div>\n<p>מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;x&lt;c\\)</span>,</span></span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(t\\mapsto t^2\\)</span> עולה ממש על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c^2&gt;x^2\\)</span>.</span> יחד עם הנתון <span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)&gt;c^2\\)</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)&gt;x^2\\)</span>.</span> כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y-x&gt;0\\)</span>,</span></span> הכפלה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(y-x\\)</span></span> נותנת:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(y)-f(x)=f'(c)(y-x)&gt;x^2(y-x).\\]</div>\n<p><em>למה?</em> תנאי הרציפות של משפט לגראנז׳ בקצוות <span class=\"math math-inline\" dir=\"ltr\">\\([x,y]\\)</span> מתקיים אוטומטית כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> ושם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה ולכן גם רציפה.</p>\n<p><strong>שלב 2: הפרכת הרציפות במידה שווה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></strong> נבדוק ישירות את שלילת הגדרה 5.46 עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0=1&gt;0\\)</span>:</span> יהי <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> כלשהו. לפי תכונת ארכימדס (המספרים הטבעיים אינם חסומים מלעיל), קיים <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;\\frac{1}{\\delta}\\)</span>,</span></span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n}&lt;\\delta\\)</span>.</span> נבחר שתי נקודות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>:</span></span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[x=n, \\qquad y=n+\\frac{1}{n}.\\]</div>\n<p>מתקיימים <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;x&lt;y\\)</span> וגם:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|y-x|=\\frac{1}{n}&lt;\\delta.\\]</div>\n<p>מצד שני, משלב 1 נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f(y)-f(x)|\\ge f(y)-f(x)&gt;x^2(y-x)=n^2\\cdot\\frac{1}{n}=n\\ge 1=\\varepsilon_0.\\]</div>\n<p>(אם רוצים לראות זאת גם דרך אפיון סדרתי: הסדרות <span class=\"math math-inline\" dir=\"ltr\">\\(x_n=n, y_n=n+\\frac{1}{n}\\)</span> מקיימות <span class=\"math math-inline\" dir=\"ltr\">\\(y_n-x_n=\\frac{1}{n}\\to 0\\)</span> בזמן <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(y_n)-f(x_n)&gt;n\\)</span>,</span></span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> בהכרח אינה רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.)</span></span></p>\n<p><strong>שלב 3: מסקנה.</strong> מצאנו <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0=1&gt;0\\)</span> שעבורו לכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> קיימות נקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in(0,\\infty)\\)</span> במרחק קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span></span> שהפרש ערכי הפונקציה בהן הוא לפחות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span></p></div></div>","steps":["<p><strong>שלב 1: הוכחת ההדרכה בעזרת משפט לגראנז׳.</strong> יהיו <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in(0,\\infty)\\)</span> המקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;y\\)</span>.</span> הקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([x,y]\\)</span> מוכל <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span></span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([x,y]\\)</span>.</span> ממשפט 7.9 (גזירות גוררת רציפות) נובע כי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([x,y]\\)</span>,</span></span> ובפרט גזירה בקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((x,y)\\)</span>.</span> לפי משפט לגראנז׳ (משפט 8.6) על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([x,y]\\)</span>,</span> קיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(x,y)\\)</span> כך ש:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(y)-f(x)=f'(c)(y-x).\\]</div>\n<p>מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;x&lt;c\\)</span>,</span></span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(t\\mapsto t^2\\)</span> עולה ממש על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c^2&gt;x^2\\)</span>.</span> יחד עם הנתון <span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)&gt;c^2\\)</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)&gt;x^2\\)</span>.</span> כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y-x&gt;0\\)</span>,</span></span> הכפלה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(y-x\\)</span></span> נותנת:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(y)-f(x)=f'(c)(y-x)&gt;x^2(y-x).\\]</div>\n<p><em>למה?</em> תנאי הרציפות של משפט לגראנז׳ בקצוות <span class=\"math math-inline\" dir=\"ltr\">\\([x,y]\\)</span> מתקיים אוטומטית כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> ושם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה ולכן גם רציפה.</p>","<p><strong>שלב 2: הפרכת הרציפות במידה שווה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></strong> נבדוק ישירות את שלילת הגדרה 5.46 עם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0=1&gt;0\\)</span>:</span> יהי <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> כלשהו. לפי תכונת ארכימדס (המספרים הטבעיים אינם חסומים מלעיל), קיים <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> כך <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n&gt;\\frac{1}{\\delta}\\)</span>,</span></span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n}&lt;\\delta\\)</span>.</span> נבחר שתי נקודות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>:</span></span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[x=n, \\qquad y=n+\\frac{1}{n}.\\]</div>\n<p>מתקיימים <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;x&lt;y\\)</span> וגם:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|y-x|=\\frac{1}{n}&lt;\\delta.\\]</div>\n<p>מצד שני, משלב 1 נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f(y)-f(x)|\\ge f(y)-f(x)&gt;x^2(y-x)=n^2\\cdot\\frac{1}{n}=n\\ge 1=\\varepsilon_0.\\]</div>\n<p>(אם רוצים לראות זאת גם דרך אפיון סדרתי: הסדרות <span class=\"math math-inline\" dir=\"ltr\">\\(x_n=n, y_n=n+\\frac{1}{n}\\)</span> מקיימות <span class=\"math math-inline\" dir=\"ltr\">\\(y_n-x_n=\\frac{1}{n}\\to 0\\)</span> בזמן <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(y_n)-f(x_n)&gt;n\\)</span>,</span></span> כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> בהכרח אינה רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.)</span></span></p>","<p><strong>שלב 3: מסקנה.</strong> מצאנו <span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon_0=1&gt;0\\)</span> שעבורו לכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> קיימות נקודות <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in(0,\\infty)\\)</span> במרחק קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span></span> שהפרש ערכי הפונקציה בהן הוא לפחות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לחשוב שמספיק להראות <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\to\\infty\\)</span> — בלי תיאור ההגדרה או לגראנז׳ זה רק רעיון אינטואיטיבי, לא הוכחה מלאה (למשל, יש פונקציות שרציפות במ&quot;ש בקטע פתוח חסום אף שנגזרתן שואפת לאינסוף, כמו <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x}\\)</span> ליד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>!).</span> כאן חייבים לצעוד עם <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span> למקומות שבהם גם <span class=\"math math-inline\" dir=\"ltr\">\\(y-x&lt;\\delta\\)</span> עדיין מניב הפרש גבהים שלפחות קבוע חיובי.</li><li>לבחור <span class=\"math math-inline\" dir=\"ltr\">\\(y-x=\\delta\\)</span> ואז להשתמש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(|y-x|&lt;\\delta\\)</span></span> (כך שהנקודות אינן במרחק קטן <em>ממש</em> <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span>)</span></span> — חשוב לקחת צעד קטן ממש <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span>,</span></span> כגון <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n}&lt;\\delta\\)</span> או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\delta}{2}\\)</span>.</span></li></ul></div></div>"}],"similar":"<p><strong>שאלות דומות</strong>: <a href=\"#/exams/31/q2\">2024א · מועד 96, שאלה 2</a> · <a href=\"#/exams/45/q6\">2026ג · מועד 83, שאלה 6</a></p>","mc":null,"options":["א","ב"]},"3":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(25 נקודות) תהי <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> סדרה הנתונה ע&quot;י: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_1=\\frac{1}{2},\\ a_{n+1}=a_n^2+a_n^3\\)</span>,</span> תהי <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> סדרה הנתונה ע&quot;י: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_1=-1,\\ b_{n+1}=b_n^2+b_n^3\\)</span>,</span> ותהי <span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span> סדרה הנתונה ע&quot;י <span class=\"math math-inline\" dir=\"ltr\">\\(c_n=\\begin{cases}a_n &amp; n\\text{ odd}\\\\ b_n &amp; n\\text{ even}\\end{cases}\\)</span> (<code dir=\"auto\">odd</code> – אי-זוגי, <code dir=\"auto\">even</code> – זוגי). הוכיחו שהסדרות <span class=\"math math-inline\" dir=\"ltr\">\\((a_n),\\ (b_n)\\)</span> מתכנסות, וקבעו האם <span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span> מתכנסת.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> יורדת בתוך <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\frac{1}{2}]\\)</span> ומתכנסת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>;</span></span> הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> מגיעה ישר לאפס כבר באיבר השני ונשארת שם; ולכן גם הסדרה המשולבת <span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span> שלוקחת לסירוגין מפה ומשם מתכנסת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> יורדת בתוך <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\frac{1}{2}]\\)</span> ומתכנסת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>;</span></span> הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> מגיעה ישר לאפס כבר באיבר השני ונשארת שם; ולכן גם הסדרה המשולבת <span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span> שלוקחת לסירוגין מפה ומשם מתכנסת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p>\n<p><strong>תמונה בראש</strong>: תחשבו על מדרון שאם מתחילים בו בגובה <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{2}\\)</span> ומחליקים לפי הכלל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\mapsto x^2+x^3\\)</span>,</span> בכל צעד נופלים נמוך יותר ויותר לכיוון הקרקע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span> לעומת זאת, אם מתחילים <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span>,</span></span> הכלל <span class=\"math math-inline\" dir=\"ltr\">\\(b_2=(-1)^2+(-1)^3=1-1=0\\)</span> זורק אותנו ישר לקרקע <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> בצעד הראשון, ומשם כבר לא זזים. כשמערבבים שני מסלולים שמגיעים לאותה קרקע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span> גם המסלול המעורב מגיע <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p>\n<p><strong>עם מספרים</strong>:</p>\n<ul><li>בסדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span>:</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_1=0.5\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_2=0.25+0.125=0.375\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_3\\approx 0.193\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_4\\approx 0.045\\)</span>.</span> יורדת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></li><li>בסדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span>:</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_1=-1\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_2=1-1=0\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_3=0^2+0^3=0\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(b_4=0,\\dots\\)</span> (קבועה <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> החל מהשני!).</li><li>בסדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span>:</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c_1=a_1=0.5\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c_2=b_2=0\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c_3=a_3\\approx 0.193\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(c_4=b_4=0,\\dots\\)</span> — הזוגיים הם כבר <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> והאי-זוגיים יורדים <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></li></ul>\n<p><strong>סדרה רקורסיבית</strong> היא סדרה שכל איבר בה מחושב מתוך האיבר הקודם לו. <strong>סדרה מתכנסת</strong> שואפת למספר אחד סופי; אם גם תת-הסדרה של האינדקסים האי-זוגיים וגם של הזוגיים מתכנסות <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> אז הסדרה כולה מתכנסת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x^2+x^3\\)</span> שמעבירה כל איבר לאיבר הבא, ובירוק מקווקו הישר <span class=\"math math-inline\" dir=\"ltr\">\\(y=x\\)</span> (נקודות השבת הן איפה שהן נפגשות). האדומה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((-1,0)\\)</span></span> מראה את <span class=\"math math-inline\" dir=\"ltr\">\\(b_1=-1\\)</span> קופצת מיד אל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_2=0\\)</span>,</span> והנקודות הכתומות מראות את <span class=\"math math-inline\" dir=\"ltr\">\\(a_1=0.5\\mapsto a_2=0.375\\mapsto a_3\\approx 0.193\\)</span> מחליקות שמאלה ולמטה אל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span>.</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-1.25,&quot;xmax&quot;:0.9,&quot;ymin&quot;:-0.25,&quot;ymax&quot;:0.85}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=x^{2}+x^{3}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;id&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=x&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;b1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(-1,0)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;a1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0.5,0.375)&quot;,&quot;color&quot;:&quot;#fa7e19&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;a2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0.375,0.193)&quot;,&quot;color&quot;:&quot;#fa7e19&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;lim&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,0)&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: בדקו קודם את $(b_n)$ — יש הפתעה!","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: בדקו קודם את <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> — יש הפתעה!</p><div class=\"callout-body\"><p>חשבו את <span class=\"math math-inline\" dir=\"ltr\">\\(b_2\\)</span> ואת <span class=\"math math-inline\" dir=\"ltr\">\\(b_3\\)</span> מתוך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_1=-1\\)</span>.</span> לאן הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> מגיעה מיד?</p></div></div>"},{"title":"רמז 2: הוכיחו חסימות וירידה של $(a_n)$ באינדוקציה","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: הוכיחו חסימות וירידה של <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> באינדוקציה</p><div class=\"callout-body\"><p>הראו באינדוקציה שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a_n\\le\\frac{1}{2}\\)</span>,</span> ובנוסף <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{n+1}=a_n(a_n+a_n^2)\\le \\frac{3}{4}a_n &lt; a_n\\)</span>.</span> מכאן משפט ההתכנסות המונוטונית (3.16) מסיים!</p></div></div>"},{"title":"רמז 3: מה הגבול של $(a_n)$ ואיך זה קובע את $(c_n)$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: מה הגבול של <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> ואיך זה קובע את <span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span></p><div class=\"callout-body\"><p>עברו לגבול במשוואת הרקורסיה של <span class=\"math math-inline\" dir=\"ltr\">\\(a_n\\)</span> כדי למצוא <span class=\"math math-inline\" dir=\"ltr\">\\(L=L^2+L^3\\)</span> (ושימו לב <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\in[0,\\frac{1}{2}]\\)</span>).</span></span> כעת השוו בין גבול האיברים הזוגיים והאי-זוגיים של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span>!</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>ננתח כל סדרה בתורה: עבור <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> נוכיח באינדוקציה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a_n\\le\\frac{1}{2}\\)</span></span> ושהיא יורדת ממש, ולכן מתכנסת לגבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L\\in[0,\\frac{1}{2}]\\)</span>;</span> ממעבר לגבול ברקורסיה נסיק <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=0\\)</span>.</span></span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> נחשב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_2=0\\)</span>,</span> נוכיח באינדוקציה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(b_n=0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span>,</span> ולכן גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim b_n=0\\)</span>.</span> לבסוף נשתמש בכך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\le c_n\\le a_n\\)</span></span> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span> (או בהתכנסות שתי תתי-הסדרות הזוגית והאי-זוגית <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>)</span></span> כדי להסיק <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span></span> מתכנסת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: חסימות ומונוטוניות של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span>.</span></strong> נוכיח באינדוקציה שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a_n\\le\\frac{1}{2}\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{n+1}&lt;a_n\\)</span>:</span></p>\n<ul><li><strong>בסיס <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(n=1\\)</span>)</span></strong>: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_1=\\frac{1}{2}\\)</span>,</span> שאכן מקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;\\frac{1}{2}\\le\\frac{1}{2}\\)</span>.</span></li><li><strong>צעד האינדוקציה</strong>: נניח כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a_n\\le\\frac{1}{2}\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;0\\)</span>,</span></span> מתקיים גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{n+1}=a_n^2+a_n^3&gt;0\\)</span>.</span> בנוסף, כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a_n\\le\\frac{1}{2}\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n^2\\le\\frac{1}{4}\\)</span>,</span> ולכן:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[a_{n+1}=a_n(a_n+a_n^2)\\le a_n\\left(\\frac{1}{2}+\\frac{1}{4}\\right)=\\frac{3}{4}a_n &lt; a_n \\le \\frac{1}{2}.\\]</div>\n<p>לפיכך הוכחנו באינדוקציה שהסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> חסומה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a_n\\le\\frac{1}{2}\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>)</span> ומונוטונית יורדת ממש <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a_{n+1}&lt;a_n\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>).</span> לפי המשפט על סדרה מונוטונית וחסומה (משפט 3.16), הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> מתכנסת לגבול סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=\\lim_{n\\to\\infty}a_n\\)</span>.</span></p>\n<p><em>למה?</em> אם ננסה רק משוואה ריבועית על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{n+1}-a_n\\)</span>,</span> קל לפספס למה <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{2}\\)</span> נשמר. הפירוק <span class=\"math math-inline\" dir=\"ltr\">\\(a_{n+1}=a_n(a_n+a_n^2)\\)</span> מראה מיידית שמכפילים כל איבר בפחות <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{3}{4}\\)</span>,</span></span> אז הוא חייב גם להישאר מתחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{2}\\)</span></span> וגם לקטון בכל צעד.</p>\n<p><strong>שלב 2: חישוב הגבול של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span>.</span></strong> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a_n\\le\\frac{1}{2}\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>,</span> משפט שמירת אי-השוויונות (משפט 2.31) נותן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le L\\le\\frac{1}{2}\\)</span>.</span> כמו כן <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_{n+1}=L\\)</span> (הזזת אינדקס, משפט 2.17/2.29). במעבר לגבול בשוויון <span class=\"math math-inline\" dir=\"ltr\">\\(a_{n+1}=a_n^2+a_n^3\\)</span> לפי אריתמטיקה של גבולות (משפט 2.28) נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L=L^2+L^3 \\implies L(L^2+L-1)=0.\\]</div>\n<p>לכן או <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=0\\)</span>,</span></span> או <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L^2+L-1=0\\)</span>.</span></span> אולם עבור <span class=\"math math-inline\" dir=\"ltr\">\\(0\\le L\\le\\frac{1}{2}\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L^2+L-1\\le \\left(\\frac{1}{2}\\right)^2+\\frac{1}{2}-1=-\\frac{1}{4}&lt;0.\\]</div>\n<p>לכן הגורם <span class=\"math math-inline\" dir=\"ltr\">\\(L^2+L-1\\)</span> אינו יכול להתאפס בתחום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\frac{1}{2}]\\)</span>,</span> ובהכרח:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}a_n=0.\\]</div>\n<p><strong>שלב 3: התכנסות <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> וחישוב גבולה.</strong> נחשב את האיבר השני מתוך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_1=-1\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[b_2=b_1^2+b_1^3=(-1)^2+(-1)^3=1-1=0.\\]</div>\n<p>מכאן באינדוקציה, אם <span class=\"math math-inline\" dir=\"ltr\">\\(b_n=0\\)</span> (עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span>),</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_{n+1}=0^2+0^3=0\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(b_n=0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span>.</span> כיוון ששינוי האיבר הראשון בלבד אינו משנה התכנסות וגבול (משפט 2.17 וטענה 2.11), הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> מתכנסת ומתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}b_n=0.\\]</div>\n<p><strong>שלב 4: קביעת התכנסות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span>.</span></strong> נבחן את <span class=\"math math-inline\" dir=\"ltr\">\\(c_n\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span>:</span></p>\n<ul><li>אם <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> אי-זוגי <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 3\\)</span>),</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c_n=a_n\\in(0,a_n]\\)</span>.</span></li><li>אם <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> זוגי <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span>),</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c_n=b_n=0\\in[0,a_n]\\)</span>.</span></li></ul>\n<p>לכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le c_n\\le a_n\\)</span>.</span> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=0\\)</span></span> (משלב 2) והסדרה הקבועה <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> שואפת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> לפי משפט הסנדוויץ׳ (משפט 2.32, תוך שימוש בזנב <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span> לפי משפט 2.17) נקבל כי <span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span> מתכנסת וגם:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}c_n=0.\\]</div></div></div>","steps":["<p><strong>שלב 1: חסימות ומונוטוניות של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span>.</span></strong> נוכיח באינדוקציה שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a_n\\le\\frac{1}{2}\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{n+1}&lt;a_n\\)</span>:</span></p>\n<ul><li><strong>בסיס <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(n=1\\)</span>)</span></strong>: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_1=\\frac{1}{2}\\)</span>,</span> שאכן מקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;\\frac{1}{2}\\le\\frac{1}{2}\\)</span>.</span></li><li><strong>צעד האינדוקציה</strong>: נניח כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a_n\\le\\frac{1}{2}\\)</span>.</span> מכיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n&gt;0\\)</span>,</span></span> מתקיים גם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{n+1}=a_n^2+a_n^3&gt;0\\)</span>.</span> בנוסף, כיוון <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a_n\\le\\frac{1}{2}\\)</span>,</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_n^2\\le\\frac{1}{4}\\)</span>,</span> ולכן:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[a_{n+1}=a_n(a_n+a_n^2)\\le a_n\\left(\\frac{1}{2}+\\frac{1}{4}\\right)=\\frac{3}{4}a_n &lt; a_n \\le \\frac{1}{2}.\\]</div>\n<p>לפיכך הוכחנו באינדוקציה שהסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> חסומה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a_n\\le\\frac{1}{2}\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>)</span> ומונוטונית יורדת ממש <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a_{n+1}&lt;a_n\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>).</span> לפי המשפט על סדרה מונוטונית וחסומה (משפט 3.16), הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span> מתכנסת לגבול סופי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=\\lim_{n\\to\\infty}a_n\\)</span>.</span></p>\n<p><em>למה?</em> אם ננסה רק משוואה ריבועית על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_{n+1}-a_n\\)</span>,</span> קל לפספס למה <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{2}\\)</span> נשמר. הפירוק <span class=\"math math-inline\" dir=\"ltr\">\\(a_{n+1}=a_n(a_n+a_n^2)\\)</span> מראה מיידית שמכפילים כל איבר בפחות <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{3}{4}\\)</span>,</span></span> אז הוא חייב גם להישאר מתחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{2}\\)</span></span> וגם לקטון בכל צעד.</p>","<p><strong>שלב 2: חישוב הגבול של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a_n)\\)</span>.</span></strong> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;a_n\\le\\frac{1}{2}\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>,</span> משפט שמירת אי-השוויונות (משפט 2.31) נותן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le L\\le\\frac{1}{2}\\)</span>.</span> כמו כן <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_{n+1}=L\\)</span> (הזזת אינדקס, משפט 2.17/2.29). במעבר לגבול בשוויון <span class=\"math math-inline\" dir=\"ltr\">\\(a_{n+1}=a_n^2+a_n^3\\)</span> לפי אריתמטיקה של גבולות (משפט 2.28) נקבל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L=L^2+L^3 \\implies L(L^2+L-1)=0.\\]</div>\n<p>לכן או <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=0\\)</span>,</span></span> או <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L^2+L-1=0\\)</span>.</span></span> אולם עבור <span class=\"math math-inline\" dir=\"ltr\">\\(0\\le L\\le\\frac{1}{2}\\)</span> מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L^2+L-1\\le \\left(\\frac{1}{2}\\right)^2+\\frac{1}{2}-1=-\\frac{1}{4}&lt;0.\\]</div>\n<p>לכן הגורם <span class=\"math math-inline\" dir=\"ltr\">\\(L^2+L-1\\)</span> אינו יכול להתאפס בתחום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\frac{1}{2}]\\)</span>,</span> ובהכרח:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}a_n=0.\\]</div>","<p><strong>שלב 3: התכנסות <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> וחישוב גבולה.</strong> נחשב את האיבר השני מתוך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_1=-1\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[b_2=b_1^2+b_1^3=(-1)^2+(-1)^3=1-1=0.\\]</div>\n<p>מכאן באינדוקציה, אם <span class=\"math math-inline\" dir=\"ltr\">\\(b_n=0\\)</span> (עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span>),</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_{n+1}=0^2+0^3=0\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(b_n=0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span>.</span> כיוון ששינוי האיבר הראשון בלבד אינו משנה התכנסות וגבול (משפט 2.17 וטענה 2.11), הסדרה <span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span> מתכנסת ומתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}b_n=0.\\]</div>","<p><strong>שלב 4: קביעת התכנסות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span>.</span></strong> נבחן את <span class=\"math math-inline\" dir=\"ltr\">\\(c_n\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span>:</span></p>\n<ul><li>אם <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> אי-זוגי <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 3\\)</span>),</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c_n=a_n\\in(0,a_n]\\)</span>.</span></li><li>אם <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> זוגי <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span>),</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c_n=b_n=0\\in[0,a_n]\\)</span>.</span></li></ul>\n<p>לכן לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le c_n\\le a_n\\)</span>.</span> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}a_n=0\\)</span></span> (משלב 2) והסדרה הקבועה <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> שואפת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> לפי משפט הסנדוויץ׳ (משפט 2.32, תוך שימוש בזנב <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span> לפי משפט 2.17) נקבל כי <span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span> מתכנסת וגם:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}c_n=0.\\]</div>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לראות את <span class=\"math math-inline\" dir=\"ltr\">\\(b_1=-1\\)</span> ולהניח בלי לבדוק <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\((b_n)\\)</span></span> מתנהגת מסובך או מתבדרת — הצבת האיבר הראשון מראה מיד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b_2=0\\)</span>!</span></li><li>להניח בלי הוכחה שכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(L=L^2+L^3\\)</span></span> והשורשים האחרים אי-רציונליים, אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(L=0\\)</span>:</span> לשורש <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{-1+\\sqrt{5}}{2}\\approx 0.618\\)</span> יש משמעות אמיתית (אם מתחילים <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a_1=0.7\\)</span>,</span></span> הסדרה דווקא בורחת לאינסוף!). חייבים לנמק בעזרת החסם <span class=\"math math-inline\" dir=\"ltr\">\\(L\\le\\frac{1}{2}\\)</span> שהשורש החיובי פסול.</li><li>לחשוב שתתי-הסדרות הזוגית והאי-זוגית של <span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span> מתכנסות לשני גבולות שונים — כאן <em>במקרה</em> שתיהן שואפות <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\((c_n)\\)</span> מתכנסת.</li></ul></div></div>"}],"similar":"","mc":null},"4":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(25 נקודות) <strong>א.</strong> (10 נק׳) הוכיחו שהפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sqrt{x}\\sin\\sqrt{x}\\)</span> רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>.</span></span></p>\n<p><strong>ב.</strong> (15 נק׳) תהי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> פונקציה רציפה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span> וגזירה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span> נניח כי <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span> וכי <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> מונוטונית עולה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span> (1) הוכיחו שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}&lt;f'(x)\\)</span>.</span> (2) הוכיחו שהפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{f(x)}{x}\\)</span> מונוטונית עולה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></p></div></div>","parts":[{"label":"א","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">ליד <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> הפונקציה רציפה על קטע סגור ולכן רציפה במ&quot;ש לפי משפט קנטור, והחל <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span></span> הנגזרת שלה חסומה ולכן גם שם היא רציפה במ&quot;ש — ומחברים את שני החלקים בקו התפר.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: ליד <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> הפונקציה רציפה על קטע סגור ולכן רציפה במ&quot;ש לפי משפט קנטור, והחל <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span></span> הנגזרת שלה חסומה ולכן גם שם היא רציפה במ&quot;ש — ומחברים את שני החלקים בקו התפר.</p>\n<p><strong>תמונה בראש</strong>: תחשבו על כביש אינסופי שמתחיל <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span> יש בו שתי בעיות אפשריות לנהיגה: <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> השורש תלול ואינו גזיר, ומימין יש המון גלים אינסופיים <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\sin\\sqrt{x}\\)</span>).</span> הפתרון הוא לחתוך <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span>:</span></span> הקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> סגור וחסום, אז משפט קנטור דואג לו אוטומטית; <span class=\"nobr\">וב-<span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></span> השורש כבר מספיק גדול כדי לרסן את הגלים (הנגזרת נשארת קטנה <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>),</span></span> כך שהשיפוע חסום בכל הקטע האינסופי.</p>\n<p><strong>עם מספרים</strong>: עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;1\\)</span>,</span> הנוסחה לנגזרת היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=\\frac{\\sin\\sqrt{x}}{2\\sqrt{x}}+\\frac{1}{2}\\cos\\sqrt{x}\\)</span>.</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=100\\)</span></span> השבר הראשון לכל היותר <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{20}=0.05\\)</span> והשני לכל היותר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0.5\\)</span>,</span> כך שהשיפוע תמיד בין <span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span> לכן אם מרחק הקלטים קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>,</span></span> גם השינוי בפלט קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon\\)</span>.</span></span></p>\n<p><strong>רציפות במידה שווה</strong> על איחוד של שני קטעים צמודים <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></span> דורשת גם לטפל בזוג נקודות שרגל אחת שלו משמאל <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> והשנייה מימין <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> — את זה עושים עם <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\varepsilon}{2}\\)</span> בכל קטע ואי-שוויון המשולש דרך הנקודה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sqrt{x}\\sin\\sqrt{x}\\)</span>,</span> ובכתום הנגזרת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=\\frac{\\sin\\sqrt{x}}{2\\sqrt{x}}+\\frac{1}{2}\\cos\\sqrt{x}\\)</span>.</span> מימין לקו הירוק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span>,</span> הנגזרת הכתומה כלואה תמיד בין הקווים האדומים <span class=\"math math-inline\" dir=\"ltr\">\\(y=1\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=-1\\)</span>,</span></span> ולכן השיפוע של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מרוסן לאורך כל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span>.</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.5,&quot;xmax&quot;:16,&quot;ymin&quot;:-4.2,&quot;ymax&quot;:4.2}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\sqrt{x}\\\\sin(\\\\sqrt{x})&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;d&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;g(x)=\\\\frac{\\\\sin(\\\\sqrt{x})}{2\\\\sqrt{x}}+\\\\frac{1}{2}\\\\cos(\\\\sqrt{x})&quot;,&quot;color&quot;:&quot;#fa7e19&quot;},{&quot;id&quot;:&quot;cut&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=1&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;u1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;d1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=-1&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: מפצלים את התחום ל-$[0,1]$ ול-$[1,\\infty)$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: מפצלים את התחום <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span></span> <span class=\"nobr\">ול-<span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></span></p><div class=\"callout-body\"><p>על הקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה וסגורה — מה קובע משפט קנטור (5.48)?</p></div></div>"},{"title":"רמז 2: מחשבים את $f'(x)$ עבור $x>1$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: מחשבים את <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;1\\)</span></p><div class=\"callout-body\"><p>גזרו את <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sqrt{x}\\sin\\sqrt{x}\\)</span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>.</span> הראו שממש מתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(|f'(x)|&lt;1\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;1\\)</span>,</span> ובאמצעות משפט לגראנז׳ (8.6) הסיקו <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(|f(y)-f(x)|\\le|y-x|\\)</span></span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span>.</span></span></p></div></div>"},{"title":"רמז 3: אל תשכחו לחבר בנקודת התפר $x=1$!","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: אל תשכחו לחבר בנקודת התפר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span>!</span></p><div class=\"callout-body\"><p>איך מראים שפונקציה שרציפה במ&quot;ש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span></span> וגם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></span> רציפה במ&quot;ש באיחוד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>?</span> קחו <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\varepsilon}{2}\\)</span> בכל חלק!</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נפצל את <span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span> לשני קטעים <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span>:</span></span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span></span> הפונקציה רציפה ולכן רציפה במ&quot;ש לפי משפט קנטור; <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></span> נגזור את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span>,</span> נחסום <span class=\"math math-inline\" dir=\"ltr\">\\(|f'(x)|\\le 1\\)</span> ונקבל ממשפט לגראנז׳ תנאי ליפשיץ שמבטיח רציפות במ&quot;ש. לבסוף נדביק את שני החלקים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> באמצעות <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\varepsilon}{2}\\)</span> ואי-שוויון המשולש.</p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: רציפות במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span></span></strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(x\\mapsto\\sqrt{x}\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> (משפט 5.13/5.43 כהפוכה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span>),</span></span> והפונקציות <span class=\"math math-inline\" dir=\"ltr\">\\(x\\mapsto x\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sin x\\)</span></span> רציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> (משפט 5.13). מהרכבה ומכפלה של פונקציות רציפות (משפט 5.15 ואריתמטיקה 4.35), <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sqrt{x}\\sin\\sqrt{x}\\)</span> רציפה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>,</span> ובפרט בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span> לפי משפט קנטור (משפט 5.48), <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במידה שווה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span></p>\n<p><strong>שלב 2: רציפות במידה שווה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></span> דרך חסימת הנגזרת.</strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x}=x^{1/2}\\)</span> גזירה עם נגזרת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{2\\sqrt{x}}\\)</span> (משפט 7.31), <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sin u\\)</span></span> גזירה עם נגזרת <span class=\"math math-inline\" dir=\"ltr\">\\(\\cos u\\)</span> (משפט 7.26). לפי כלל המכפלה (משפט 7.14) וכלל השרשרת (משפט 7.21), <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> ונגזרתה היא:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x)=\\frac{1}{2\\sqrt{x}}\\sin\\sqrt{x}+\\sqrt{x}\\cos\\sqrt{x}\\cdot\\frac{1}{2\\sqrt{x}}=\\frac{\\sin\\sqrt{x}}{2\\sqrt{x}}+\\frac{1}{2}\\cos\\sqrt{x}.\\]</div>\n<p>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(1,\\infty)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x}&gt;1\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(|\\sin\\sqrt{x}|\\le 1\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\cos\\sqrt{x}|\\le 1\\)</span>.</span></span> מאי-שוויון המשולש (טענה 1.49):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f'(x)|\\le\\frac{|\\sin\\sqrt{x}|}{2\\sqrt{x}}+\\frac{|\\cos\\sqrt{x}|}{2}&lt;\\frac{1}{2\\cdot 1}+\\frac{1}{2}=1.\\]</div>\n<p>כעת, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[1,\\infty)\\)</span> שונים (נניח בה&quot;כ <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\le x&lt;y\\)</span>),</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([x,y]\\)</span></span> וגזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((x,y)\\)</span>,</span></span> ולכן לפי משפט לגראנז׳ (משפט 8.6) קיים <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(x,y)\\subset(1,\\infty)\\)</span> כך ש:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f(y)-f(x)|=|f'(c)|\\cdot|y-x|&lt;1\\cdot|y-x|=|y-x|.\\]</div>\n<p>(עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x=y\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le 0\\)</span>.)</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במידה שווה גם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></span> (לכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\tilde{\\varepsilon}&gt;0\\)</span> מספיק לבחור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_2=\\tilde{\\varepsilon}\\)</span>).</span></p>\n<p><em>למה?</em> אם היינו מנסים לחסום את <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span> עד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>,</span> היינו צריכים לעבוד עם <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sin\\sqrt{x}}{\\sqrt{x}}\\)</span> ליד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span> פיצול <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span></span> עוקף זאת לחלוטין: קנטור מטפל בחינם בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> <span class=\"nobr\">ומ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> ואילך <span class=\"math math-inline\" dir=\"ltr\">\\(2\\sqrt{x}&gt;2\\)</span> במכנה עושה את העבודה.</p>\n<p><strong>שלב 3: הדבקת הרציפות במידה שווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>.</span></span></strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span></p>\n<ul><li>מהרציפות במ&quot;ש של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span></span> (שלב 1) עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\varepsilon}{2}&gt;0\\)</span>,</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_1&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,1]\\)</span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta_1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\frac{\\varepsilon}{2}\\)</span>.</span></li><li>מהרציפות במ&quot;ש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></span> (שלב 2) עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\varepsilon}{2}&gt;0\\)</span>,</span> אם <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[1,\\infty)\\)</span> מקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\frac{\\varepsilon}{2}\\)</span>,</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\frac{\\varepsilon}{2}\\)</span>.</span></li></ul>\n<p>נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\min\\left(\\delta_1,\\frac{\\varepsilon}{2}\\right)&gt;0\\)</span>.</span> ניקח כעת שתי נקודות כלשהן <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,\\infty)\\)</span> המקיימות <span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta\\)</span> (נניח בה&quot;כ <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\le y\\)</span>):</span></p>\n<ol><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,1]\\)</span>,</span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta\\le\\delta_1\\)</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\frac{\\varepsilon}{2}&lt;\\varepsilon\\)</span>.</span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[1,\\infty)\\)</span>,</span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta\\le\\frac{\\varepsilon}{2}\\)</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\frac{\\varepsilon}{2}&lt;\\varepsilon\\)</span>.</span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;1&lt;y\\)</span>,</span> אזי המרחק של כל אחת מהן לנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y-x&lt;\\delta\\)</span>,</span></span> כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(|1-x|&lt;y-x&lt;\\delta\\le\\delta_1\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|y-1|&lt;y-x&lt;\\delta\\le\\frac{\\varepsilon}{2}\\)</span>.</span> לכן מאי-שוויון המשולש (טענה 1.49):</li></ol>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f(y)-f(x)|=|f(y)-f(1)+f(1)-f(x)|\\le|f(y)-f(1)|+|f(1)-f(x)|&lt;\\frac{\\varepsilon}{2}+\\frac{\\varepsilon}{2}=\\varepsilon.\\]</div>\n<p>לפי הגדרה 5.46, <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במידה שווה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>.</span></p></div></div>","steps":["<p><strong>שלב 1: רציפות במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span></span></strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(x\\mapsto\\sqrt{x}\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span> (משפט 5.13/5.43 כהפוכה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2\\)</span>),</span></span> והפונקציות <span class=\"math math-inline\" dir=\"ltr\">\\(x\\mapsto x\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sin x\\)</span></span> רציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb R\\)</span></span> (משפט 5.13). מהרכבה ומכפלה של פונקציות רציפות (משפט 5.15 ואריתמטיקה 4.35), <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sqrt{x}\\sin\\sqrt{x}\\)</span> רציפה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>,</span> ובפרט בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span> לפי משפט קנטור (משפט 5.48), <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במידה שווה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>.</span></p>","<p><strong>שלב 2: רציפות במידה שווה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></span> דרך חסימת הנגזרת.</strong> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x}=x^{1/2}\\)</span> גזירה עם נגזרת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{2\\sqrt{x}}\\)</span> (משפט 7.31), <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sin u\\)</span></span> גזירה עם נגזרת <span class=\"math math-inline\" dir=\"ltr\">\\(\\cos u\\)</span> (משפט 7.26). לפי כלל המכפלה (משפט 7.14) וכלל השרשרת (משפט 7.21), <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> ונגזרתה היא:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x)=\\frac{1}{2\\sqrt{x}}\\sin\\sqrt{x}+\\sqrt{x}\\cos\\sqrt{x}\\cdot\\frac{1}{2\\sqrt{x}}=\\frac{\\sin\\sqrt{x}}{2\\sqrt{x}}+\\frac{1}{2}\\cos\\sqrt{x}.\\]</div>\n<p>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(1,\\infty)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x}&gt;1\\)</span>,</span> <span class=\"math math-inline\" dir=\"ltr\">\\(|\\sin\\sqrt{x}|\\le 1\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|\\cos\\sqrt{x}|\\le 1\\)</span>.</span></span> מאי-שוויון המשולש (טענה 1.49):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f'(x)|\\le\\frac{|\\sin\\sqrt{x}|}{2\\sqrt{x}}+\\frac{|\\cos\\sqrt{x}|}{2}&lt;\\frac{1}{2\\cdot 1}+\\frac{1}{2}=1.\\]</div>\n<p>כעת, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[1,\\infty)\\)</span> שונים (נניח בה&quot;כ <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\le x&lt;y\\)</span>),</span> <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([x,y]\\)</span></span> וגזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((x,y)\\)</span>,</span></span> ולכן לפי משפט לגראנז׳ (משפט 8.6) קיים <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(x,y)\\subset(1,\\infty)\\)</span> כך ש:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f(y)-f(x)|=|f'(c)|\\cdot|y-x|&lt;1\\cdot|y-x|=|y-x|.\\]</div>\n<p>(עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x=y\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\le 0\\)</span>.)</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במידה שווה גם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></span> (לכל <span class=\"math math-inline\" dir=\"ltr\">\\(\\tilde{\\varepsilon}&gt;0\\)</span> מספיק לבחור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_2=\\tilde{\\varepsilon}\\)</span>).</span></p>\n<p><em>למה?</em> אם היינו מנסים לחסום את <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span> עד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>,</span> היינו צריכים לעבוד עם <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sin\\sqrt{x}}{\\sqrt{x}}\\)</span> ליד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span> פיצול <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span></span> עוקף זאת לחלוטין: קנטור מטפל בחינם בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> <span class=\"nobr\">ומ-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> ואילך <span class=\"math math-inline\" dir=\"ltr\">\\(2\\sqrt{x}&gt;2\\)</span> במכנה עושה את העבודה.</p>","<p><strong>שלב 3: הדבקת הרציפות במידה שווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>.</span></span></strong> יהי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon&gt;0\\)</span>.</span></p>\n<ul><li>מהרציפות במ&quot;ש של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span></span> (שלב 1) עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\varepsilon}{2}&gt;0\\)</span>,</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta_1&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,1]\\)</span> עם <span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta_1\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\frac{\\varepsilon}{2}\\)</span>.</span></li><li>מהרציפות במ&quot;ש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></span> (שלב 2) עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\varepsilon}{2}&gt;0\\)</span>,</span> אם <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[1,\\infty)\\)</span> מקיימים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\frac{\\varepsilon}{2}\\)</span>,</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\frac{\\varepsilon}{2}\\)</span>.</span></li></ul>\n<p>נבחר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\delta=\\min\\left(\\delta_1,\\frac{\\varepsilon}{2}\\right)&gt;0\\)</span>.</span> ניקח כעת שתי נקודות כלשהן <span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,\\infty)\\)</span> המקיימות <span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta\\)</span> (נניח בה&quot;כ <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\le y\\)</span>):</span></p>\n<ol><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[0,1]\\)</span>,</span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta\\le\\delta_1\\)</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\frac{\\varepsilon}{2}&lt;\\varepsilon\\)</span>.</span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x,y\\in[1,\\infty)\\)</span>,</span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(|x-y|&lt;\\delta\\le\\frac{\\varepsilon}{2}\\)</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)-f(y)|&lt;\\frac{\\varepsilon}{2}&lt;\\varepsilon\\)</span>.</span></li><li>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&lt;1&lt;y\\)</span>,</span> אזי המרחק של כל אחת מהן לנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> קטן <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y-x&lt;\\delta\\)</span>,</span></span> כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(|1-x|&lt;y-x&lt;\\delta\\le\\delta_1\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|y-1|&lt;y-x&lt;\\delta\\le\\frac{\\varepsilon}{2}\\)</span>.</span> לכן מאי-שוויון המשולש (טענה 1.49):</li></ol>\n<div class=\"math math-display\" dir=\"ltr\">\\[|f(y)-f(x)|=|f(y)-f(1)+f(1)-f(x)|\\le|f(y)-f(1)|+|f(1)-f(x)|&lt;\\frac{\\varepsilon}{2}+\\frac{\\varepsilon}{2}=\\varepsilon.\\]</div>\n<p>לפי הגדרה 5.46, <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במידה שווה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>.</span></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לטעון &quot;רציפה במ&quot;ש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span></span> ורציפה במ&quot;ש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([1,\\infty)\\)</span></span> לכן רציפה במ&quot;ש <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span></span>&quot; בלי הוכחת ההדבקה עם <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\varepsilon}{2}\\)</span> — איחוד של שני תחומים שכל אחד מהם רציף במ&quot;ש אינו בהכרח רציף במ&quot;ש אם אין להם חפיפה או נקודת מפגש רציפה! (אפילו על <span class=\"math math-inline\" dir=\"ltr\">\\([0,1)\\cup(1,2]\\)</span> אפשר לקפוץ <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.)</span></span></li><li>לחשוב בטעות שכיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x}\\)</span></span> בחוץ, <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sqrt{x}\\sin\\sqrt{x}\\)</span> מתנהגת כמו <span class=\"math math-inline\" dir=\"ltr\">\\(x\\sin x\\)</span> ואינה רציפה במ&quot;ש: ההפך הוא הנכון, כי הנגזרת של <span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x}\\)</span> יורדת כמו <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{2\\sqrt{x}}\\)</span> ומאזנת את <span class=\"nobr\">ה-<span class=\"math math-inline\" dir=\"ltr\">\\(\\sqrt{x}\\)</span></span> הכופל!</li></ul></div></div>"},{"label":"ב(1)","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">הביטוי <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}\\)</span> הוא השיפוע הממוצע של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> עד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>,</span> שכבר קורה לפי לגראנז׳ בנקודה פנימית <span class=\"math math-inline\" dir=\"ltr\">\\(c&lt;x\\)</span> — ומכיוון שהשיפוע <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> רק עולה, השיפוע בקצה הימני <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span> חייב להיות גדול יותר.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: הביטוי <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}\\)</span> הוא השיפוע הממוצע של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> עד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>,</span> שכבר קורה לפי לגראנז׳ בנקודה פנימית <span class=\"math math-inline\" dir=\"ltr\">\\(c&lt;x\\)</span> — ומכיוון שהשיפוע <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> רק עולה, השיפוע בקצה הימני <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span> חייב להיות גדול יותר.</p>\n<p><strong>תמונה בראש</strong>: תחשבו על מכונית שנוסעת מאפס והלאה, ושהמהירות שלה <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> <em>תמיד עולה</em> ככל שהזמן עובר (תאוצה קדימה כל הזמן). המהירות הממוצעת שלה מהזינוק עד רגע <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> (ששווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)-f(0)}{x-0}=\\frac{f(x)}{x}\\)</span>)</span></span> שווה לפי לגראנז׳ למהירות הרגעית ברגע מוקדם יותר <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> שבין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>.</span></span> מאחר שהמכונית המשיכה להאיץ <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span></span> עד <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span>,</span> המהירות בסוף <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span> גדולה מהמהירות באמצע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)\\)</span>.</span></p>\n<p><strong>עם מספרים</strong>: ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x^2\\)</span> (רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>,</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span>,</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=2x\\)</span></span> עולה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>).</span></span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=3\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(3)}{3}=\\frac{9}{3}=3\\)</span>,</span> שווה לנגזרת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c=1.5\\in(0,3)\\)</span>,</span></span> וזה אכן קטן ממש <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(3)=6\\)</span>.</span></span></p>\n<p>בקורס זה, המונח <strong>&quot;מונוטונית עולה&quot;</strong> (הגדרה 4.7) פירושו <strong>עולה ממש</strong>: אם <span class=\"math math-inline\" dir=\"ltr\">\\(c&lt;x\\)</span> אז <span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)&lt;f'(x)\\)</span> (אחרת, למשל עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span>,</span> מתקיים שוויון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}=1=f'(x)\\)</span>).</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול הפרבולה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x^2\\)</span> (שמקיימת <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=2x\\)</span></span> עולה). הזיזו את הסליידר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t\\)</span>:</span> הקו הירוק המקווקו הוא המיתר <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span></span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\((t,f(t))\\)</span></span> ששיפועו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(t)}{t}\\)</span>,</span> והקו האדום הוא המשיק <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((t,f(t))\\)</span></span> ששיפועו <span class=\"math math-inline\" dir=\"ltr\">\\(f'(t)\\)</span> — המשיק בקצה הימני תמיד תלול יותר מהמיתר.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.2,&quot;xmax&quot;:2.5,&quot;ymin&quot;:-0.3,&quot;ymax&quot;:5}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;t&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;t=1.3&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.4,&quot;max&quot;:2,&quot;step&quot;:0.1}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=x^{2}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;sec&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=t x&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;tan&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=f(t)+2t(x-t)&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;pt&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t,f(t))&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: זיהוי מנת לגראנז׳","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: זיהוי מנת לגראנז׳</p><div class=\"callout-body\"><p>כתבו את <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}\\)</span> בתור <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)-f(0)}{x-0}\\)</span> והפעילו משפט מתאים על הקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span>.</span></p></div></div>"},{"title":"רמז 2: שימוש במונוטוניות של $f'$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: שימוש במונוטוניות של <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span></p><div class=\"callout-body\"><p>אם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,x)\\)</span>,</span> איך קשורים <span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span></span> לפי ההנחה <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span></span> מונוטונית עולה (הגדרה 4.7) <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>?</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> שרירותי, נפעיל את משפט לגראנז׳ על <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span> (שבו <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה על הסגור וגזירה על הפתוח), ניעזר <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span></span> כדי להשוות את <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)\\)</span></span> עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,x)\\)</span>,</span> ומהעלייה הממש של <span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span> נסיק <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)&lt;f'(x)\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: הפעלת משפט לגראנז׳ על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span>.</span></strong> יהי <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> כלשהו. לפי הנתונים, <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span> ובפרט בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span>,</span> וגזירה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> ובפרט בקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,x)\\)</span>.</span> לכן תנאי משפט לגראנז׳ (משפט 8.6) מתקיימים עבור <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span>,</span> וקיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,x)\\)</span> כך ש:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{f(x)-f(0)}{x-0}=f'(c).\\]</div>\n<p><strong>שלב 2: הצבת <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span> ושימוש במונוטוניות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span>.</span></strong> כיוון שנתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span>,</span> השוויון בשלב 1 הופך ל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{f(x)}{x}=f'(c).\\]</div>\n<p>מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,x)\\)</span>,</span></span> שתי הנקודות <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> נמצאות בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> ומקיימות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&lt;x\\)</span>.</span> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span></span> מונוטונית עולה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> (במובן החזק של הקורס, הגדרה 4.7), מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(c)&lt;f'(x).\\]</div>\n<p>בהצבת <span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)=\\frac{f(x)}{x}\\)</span> נקבל כי לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{f(x)}{x}&lt;f'(x).\\]</div>\n<p><em>למה?</em> משפט לגראנז׳ אינו דורש <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> תהיה גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> עצמה — מספיקה רציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span></span> וגזירות בקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,x)\\)</span>,</span> ואלו נתונות במפורש בשאלה!</p></div></div>","steps":["<p><strong>שלב 1: הפעלת משפט לגראנז׳ על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span>.</span></strong> יהי <span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span> כלשהו. לפי הנתונים, <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span> ובפרט בקטע הסגור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span>,</span> וגזירה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> ובפרט בקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,x)\\)</span>.</span> לכן תנאי משפט לגראנז׳ (משפט 8.6) מתקיימים עבור <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span>,</span> וקיימת נקודה <span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,x)\\)</span> כך ש:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{f(x)-f(0)}{x-0}=f'(c).\\]</div>","<p><strong>שלב 2: הצבת <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span> ושימוש במונוטוניות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span>.</span></strong> כיוון שנתון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span>,</span> השוויון בשלב 1 הופך ל:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{f(x)}{x}=f'(c).\\]</div>\n<p>מאחר <span class=\"nobr\">ש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c\\in(0,x)\\)</span>,</span></span> שתי הנקודות <span class=\"math math-inline\" dir=\"ltr\">\\(c\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span></span> נמצאות בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> ומקיימות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(c&lt;x\\)</span>.</span> כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span></span> מונוטונית עולה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> (במובן החזק של הקורס, הגדרה 4.7), מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(c)&lt;f'(x).\\]</div>\n<p>בהצבת <span class=\"math math-inline\" dir=\"ltr\">\\(f'(c)=\\frac{f(x)}{x}\\)</span> נקבל כי לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\frac{f(x)}{x}&lt;f'(x).\\]</div>\n<p><em>למה?</em> משפט לגראנז׳ אינו דורש <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> תהיה גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> עצמה — מספיקה רציפות <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([0,x]\\)</span></span> וגזירות בקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,x)\\)</span>,</span> ואלו נתונות במפורש בשאלה!</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>להפעיל את משפט לגראנז׳ בלי לבדוק תנאים <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span>:</span></span> חשוב לציין במפורש <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה גם <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span></span> (נתון רציפות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>)</span></span> וגזירה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,x)\\)</span>,</span></span> בלי לדרוש גזירות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span></li><li>לשכוח שבהגדרת הקורס (הגדרה 4.7) &quot;מונוטונית עולה&quot; היא עולה ממש (ולכן אי-השוויון בסעיף הוא חזק: <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(&lt;\\)</span>).</span></li></ul></div></div>"},{"label":"ב(2)","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">כשגוזרים את <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{f(x)}{x}\\)</span> רואים שהמונה הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x f'(x)-f(x)\\)</span>,</span> ולפי סעיף ב(1) הביטוי הזה חיובי תמיד — לכן <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)&gt;0\\)</span> והפונקציה עולה ממש.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: כשגוזרים את <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{f(x)}{x}\\)</span> רואים שהמונה הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x f'(x)-f(x)\\)</span>,</span> ולפי סעיף ב(1) הביטוי הזה חיובי תמיד — לכן <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)&gt;0\\)</span> והפונקציה עולה ממש.</p>\n<p><strong>תמונה בראש</strong>: הביטוי <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{f(x)}{x}\\)</span> הוא השיפוע של הקרן מהראשית <span class=\"math math-inline\" dir=\"ltr\">\\((0,0)\\)</span> אל הנקודה <span class=\"math math-inline\" dir=\"ltr\">\\((x,f(x))\\)</span> על הגרף. ברגע שזזים מעט ימינה על העקומה, הנגזרת שם <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span> (הכיוון הרגעי של הנסיעה) גבוהה יותר מהשיפוע הממוצע עד עכשיו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)\\)</span>,</span> אז הקרן מהראשית חייבת להסתובב כלפי מעלה — כלומר <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)\\)</span> גדלה כל הזמן!</p>\n<p><strong>עם מספרים</strong>: ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x^3+x\\)</span> (רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,\\infty)\\)</span>,</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span>,</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=3x^2+1\\)</span></span> מונוטונית עולה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>).</span></span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{x^3+x}{x}=x^2+1\\)</span>,</span> שאכן עולה ממש בכל <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(g(1)=2&lt;g(2)=5&lt;g(3)=10\\)</span>),</span> והנגזרת <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)=2x&gt;0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>.</span></p>\n<p>אם הנגזרת של פונקציה גזירה חיובית ממש בכל נקודה בקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span> הפונקציה עולה ממש בכל הקטע הזה.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x^3+x\\)</span> (שמקיימת <span class=\"math math-inline\" dir=\"ltr\">\\(f(0)=0\\)</span> ונגזרתה עולה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>),</span></span> ובאדום פונקציית השיפועים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{f(x)}{x}=x^2+1\\)</span>,</span> שרואים בבירור שהיא מונוטונית עולה ממש בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.2,&quot;xmax&quot;:2.5,&quot;ymin&quot;:-0.2,&quot;ymax&quot;:6}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;t&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;t=0.8&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:0.2,&quot;max&quot;:2,&quot;step&quot;:0.1}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=x^{3}+x&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;g&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;g(x)=\\\\frac{f(x)}{x}&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;pg&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(t,g(t))&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: גוזרים את $g(x)=\\frac{f(x)}{x}$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: גוזרים את <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{f(x)}{x}\\)</span></p><div class=\"callout-body\"><p>מדוע <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> גזירה בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>?</span> חשבו את <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)\\)</span> לפי כלל המנה (משפט 7.18).</p></div></div>"},{"title":"רמז 2: שימוש בסעיף ב(1)","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: שימוש בסעיף ב(1)</p><div class=\"callout-body\"><p>הוציאו <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{x}\\)</span> גורם משותף בביטוי של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)\\)</span>,</span> והשוו לאי-השוויון מסעיף ב(1): <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)&gt;\\frac{f(x)}{x}\\)</span>.</span></p></div></div>"},{"title":"רמז 3: מהנגזרת החיובית אל המונוטוניות","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: מהנגזרת החיובית אל המונוטוניות</p><div class=\"callout-body\"><p>ברגע שמראים <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)&gt;0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span>,</span> איזה משפט (משפט 8.17 / 8.18) מסיק <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span></span> עולה ממש בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>?</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נוודא <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{f(x)}{x}\\)</span></span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> לפי כלל המנה, נסדר את הנגזרת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)=\\frac{1}{x}\\left(f'(x)-\\frac{f(x)}{x}\\right)\\)</span>,</span> ומכיוון שב-(1) הוכחנו <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)&gt;\\frac{f(x)}{x}\\)</span> וגם <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> נקבל <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)&gt;0\\)</span> בכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> מונוטונית עולה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: גזירות <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> וחישוב <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span></strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> לפי הנתון, והפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(x\\mapsto x\\)</span> גזירה ואינה מתאפסת <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>).</span> לפי כלל המנה (משפט 7.18), הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{f(x)}{x}\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> ונגזרתה היא:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g'(x)=\\frac{f'(x)\\cdot x-f(x)\\cdot 1}{x^2}=\\frac{1}{x}\\left(f'(x)-\\frac{f(x)}{x}\\right).\\]</div>\n<p><strong>שלב 2: בדיקת סימן הנגזרת והסקת מונוטוניות.</strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> ומסעיף ב(1) מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}&lt;f'(x)\\)</span>,</span> כלומר:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x)-\\frac{f(x)}{x}&gt;0.\\]</div>\n<p>מכפלת שני מספרים חיוביים חיובית, ולכן לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g'(x)=\\frac{1}{x}\\left(f'(x)-\\frac{f(x)}{x}\\right)&gt;0.\\]</div>\n<p>לפי המשפט על סימן הנגזרת ומונוטוניות (משפט 8.17), הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{f(x)}{x}\\)</span> מונוטונית עולה (עולה ממש) בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></p>\n<p><em>למה?</em> בדרך כלל כששני סעיפים באים כ-(1) ואז (2), הסעיף השני בודק האם <span class=\"math math-inline\" dir=\"ltr\">\\(g'&gt;0\\)</span> הוא בדיוק אי-השוויון שהוכחנו ב-(1)! כאן זה מדויק עד הסימן.</p></div></div>","steps":["<p><strong>שלב 1: גזירות <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> וחישוב <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></span></strong> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> לפי הנתון, והפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(x\\mapsto x\\)</span> גזירה ואינה מתאפסת <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>).</span> לפי כלל המנה (משפט 7.18), הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{f(x)}{x}\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> ונגזרתה היא:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g'(x)=\\frac{f'(x)\\cdot x-f(x)\\cdot 1}{x^2}=\\frac{1}{x}\\left(f'(x)-\\frac{f(x)}{x}\\right).\\]</div>","<p><strong>שלב 2: בדיקת סימן הנגזרת והסקת מונוטוניות.</strong> לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> ומסעיף ב(1) מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{f(x)}{x}&lt;f'(x)\\)</span>,</span> כלומר:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x)-\\frac{f(x)}{x}&gt;0.\\]</div>\n<p>מכפלת שני מספרים חיוביים חיובית, ולכן לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g'(x)=\\frac{1}{x}\\left(f'(x)-\\frac{f(x)}{x}\\right)&gt;0.\\]</div>\n<p>לפי המשפט על סימן הנגזרת ומונוטוניות (משפט 8.17), הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{f(x)}{x}\\)</span> מונוטונית עולה (עולה ממש) בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>.</span></p>\n<p><em>למה?</em> בדרך כלל כששני סעיפים באים כ-(1) ואז (2), הסעיף השני בודק האם <span class=\"math math-inline\" dir=\"ltr\">\\(g'&gt;0\\)</span> הוא בדיוק אי-השוויון שהוכחנו ב-(1)! כאן זה מדויק עד הסימן.</p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לנסות להוכיח ישירות מההגדרה <span class=\"math math-inline\" dir=\"ltr\">\\(x_1&lt;x_2 \\implies \\frac{f(x_1)}{x_1}&lt;\\frac{f(x_2)}{x_2}\\)</span> דרך קומבינציות של לגראנז׳, במקום לראות שהנגזרת של המנה <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> מתבטאת ישירות דרך אי-השוויון מ-(1).</li><li>לשכוח לציין שהמכנה <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> שונה <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> בתחום <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> כדי להצדיק את כלל המנה.</li></ul></div></div>"}],"similar":"","mc":null,"options":["א","ב"]},"5":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(5 נקודות) הגבול <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{n\\to\\infty}\\left(1-\\frac{1}{n^2}\\right)^{\\frac{n^2-1}{n}}\\)</span> הוא: א. <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> ב. <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> ג. <span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span> ד. <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{e}\\)</span> ה. <span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span></p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">זו אמנם צורה שנראית כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1^\\infty\\)</span>,</span> אבל הבסיס מתקרב <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> מהר מדי (בקצב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n^2}\\)</span>)</span> לעומת המעריך שגדל רק כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>,</span> ולכן הבסיס מנצח והחזקה שואפת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: זו אמנם צורה שנראית כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1^\\infty\\)</span>,</span> אבל הבסיס מתקרב <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> מהר מדי (בקצב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n^2}\\)</span>)</span> לעומת המעריך שגדל רק כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>,</span> ולכן הבסיס מנצח והחזקה שואפת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></p>\n<p><strong>תמונה בראש</strong>: תחשבו על משחק כוחות: הבסיס <span class=\"math math-inline\" dir=\"ltr\">\\((1-\\frac{1}{n^2})\\)</span> מושך <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> והמעריך <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{n^2-1}{n}\\approx n\\)</span> מנסה לדחוף כלפי מטה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span> אם המעריך היה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n^2\\)</span>,</span> הם היו בתיקו והיינו מקבלים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{e}\\)</span>.</span> אבל המעריך הוא רק <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> — פי <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> קטן מהכוח של <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n^2\\)</span>!</span> אפשר לכתוב את זה כ&quot;מספר שקרוב <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{e}\\)</span></span> בחזקת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{n}\\)</span>&quot;, ושורש <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>-י של <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{e}\\)</span> שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span></p>\n<p><strong>עם מספרים</strong>: <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n=10\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((1-\\frac{1}{100})^{\\frac{99}{10}}=0.99^{9.9}\\approx 0.905\\)</span>;</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n=100\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((1-\\frac{1}{10000})^{99.99}\\approx 0.990\\)</span>;</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n=1000\\)</span>:</span></span> בערך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0.999\\)</span>.</span> הסדרה עולה ומתקרבת <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>!</span></span></p>\n<p><strong>גבול מסוג <span class=\"math math-inline\" dir=\"ltr\">\\(1^\\infty\\)</span></strong> הוא גבול של ביטוי מהצורה <span class=\"math math-inline\" dir=\"ltr\">\\(A_n^{B_n}\\)</span> <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(A_n\\to 1\\)</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(B_n\\to\\infty\\)</span>.</span></span> אסור לנחש שהתוצאה היא <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> או <span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span> בלי לשקול את <em>קצב</em> השאיפה של הבסיס והמעריך.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>באדום העקומה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\left(1-\\frac{1}{x^2}\\right)^{\\frac{x^2-1}{x}}\\)</span> של הסדרה, ובכחול מקווקו קו הגבול <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=1\\)</span>.</span> הזיזו את הסליידר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span>:</span> ככל <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span></span> גדל, הנקודה האדומה מטפסת לכיוון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:1.5,&quot;xmax&quot;:30,&quot;ymin&quot;:0.4,&quot;ymax&quot;:1.15}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;n&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;n=4&quot;,&quot;sliderBounds&quot;:{&quot;min&quot;:2,&quot;max&quot;:28,&quot;step&quot;:1}},{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\left(1-\\\\frac{1}{x^{2}}\\\\right)^{\\\\frac{x^{2}-1}{x}}&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;lim&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;pn&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(n,f(n))&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: מתאימים את המעריך של הבסיס כדי ליצור את $e$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: מתאימים את המעריך של הבסיס כדי ליצור את <span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span></p><div class=\"callout-body\"><p>נסו לבודד את הביטוי <span class=\"math math-inline\" dir=\"ltr\">\\(\\left(1-\\frac{1}{n^2}\\right)^{n^2}\\)</span> מבפנים — איזה מעריך נשאר מבחוץ?</p></div></div>"},{"title":"רמז 2: מה הגבול של הפנימי ומה של החיצוני","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: מה הגבול של הפנימי ומה של החיצוני</p><div class=\"callout-body\"><p>כזכור (מסקנה 6.19), <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\left(1+\\frac{-1}{m}\\right)^m\\to e^{-1}=\\frac{1}{e}\\)</span>.</span> למה שואף המעריך החיצוני <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{n^2-1}{n^3}\\)</span>?</span></p></div></div>"},{"title":"רמז 3: סגירה בטענה 6.15","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: סגירה בטענה 6.15</p><div class=\"callout-body\"><p>אם הבסיס שואף <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{e}&gt;0\\)</span></span> והמעריך שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> למה שואפת החזקה?</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נכתוב את האיבר הכללי (עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span>)</span> כחזקה של בסיס ששואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{e}\\)</span>:</span></span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\left[\\left(1-\\frac{1}{n^2}\\right)^{n^2}\\right]^{\\frac{n^2-1}{n^3}}\\)</span>.</span> נמצא שהבסיס הפנימי שואף <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{e}&gt;0\\)</span></span> (לפי מסקנה 6.19 ותת-סדרה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(k=n^2\\)</span>)</span> והמעריך החיצוני שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> ולפי טענה 6.15 הגבול הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\left(\\frac{1}{e}\\right)^0=1\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: סידור הביטוי והתאמת המעריך.</strong> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1-\\frac{1}{n^2}&gt;0\\)</span>.</span> נכפול ונחלק את המעריך <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n^2\\)</span>:</span></span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[a_n=\\left(1-\\frac{1}{n^2}\\right)^{\\frac{n^2-1}{n}}=\\left[\\left(1-\\frac{1}{n^2}\\right)^{n^2}\\right]^{\\frac{n^2-1}{n^3}}.\\]</div>\n<p><strong>שלב 2: חישוב גבול הבסיס הפנימי וגבול המעריך החיצוני.</strong></p>\n<ul><li>לפי מסקנה 6.19, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{m\\to\\infty}\\left(1+\\frac{x}{m}\\right)^m=e^x\\)</span>.</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x=-1\\)</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{m\\to\\infty}\\left(1-\\frac{1}{m}\\right)^m=e^{-1}=\\frac{1}{e}\\)</span>.</span> הסדרה עם <span class=\"math math-inline\" dir=\"ltr\">\\(m=n^2\\)</span> היא תת-סדרה של זו (משפט 3.25), ולכן:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}\\left(1-\\frac{1}{n^2}\\right)^{n^2}=\\frac{1}{e}&gt;0.\\]</div>\n<p>(לחלופין, מהגדרת <span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span> וטענה 6.18 עם <span class=\"math math-inline\" dir=\"ltr\">\\(u_n=-\\frac{1}{n^2}\\to 0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\left(1-\\frac{1}{n^2}\\right)^{-n^2}\\to e\\)</span>,</span> ובהעלאה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span></span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{e}\\)</span>.)</span></p>\n<ul><li>עבור המעריך החיצוני:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}\\frac{n^2-1}{n^3}=\\lim_{n\\to\\infty}\\left(\\frac{1}{n}-\\frac{1}{n^3}\\right)=0-0=0.\\]</div>\n<p><em>למה?</em> הביטוי הפנימי כבר סגר את הקשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>,</span> אז המעריך שנשאר בחוץ מספר מי ניצח במרוץ: <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{n^2-1}{n^3}\\)</span> הולך <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> מה שאומר שהבסיס ניצח והחזקה נהיית מתונה לכיוון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></p>\n<p><strong>שלב 3: הסקת הגבול.</strong> הבסיס <span class=\"math math-inline\" dir=\"ltr\">\\(\\left(1-\\frac{1}{n^2}\\right)^{n^2}\\)</span> חיובי לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span> ושואף לגבול חיובי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{e}&gt;0\\)</span>,</span> והמעריך <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{n^2-1}{n^3}\\)</span> שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span> לפי טענה 6.15 (גבול של חזקה):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}a_n=\\left(\\frac{1}{e}\\right)^0=1.\\]</div>\n<p><strong>התשובה הנכונה: ב</strong></p></div></div>","steps":["<p><strong>שלב 1: סידור הביטוי והתאמת המעריך.</strong> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1-\\frac{1}{n^2}&gt;0\\)</span>.</span> נכפול ונחלק את המעריך <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n^2\\)</span>:</span></span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[a_n=\\left(1-\\frac{1}{n^2}\\right)^{\\frac{n^2-1}{n}}=\\left[\\left(1-\\frac{1}{n^2}\\right)^{n^2}\\right]^{\\frac{n^2-1}{n^3}}.\\]</div>","<p><strong>שלב 2: חישוב גבול הבסיס הפנימי וגבול המעריך החיצוני.</strong></p>\n<ul><li>לפי מסקנה 6.19, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in\\mathbb R\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{m\\to\\infty}\\left(1+\\frac{x}{m}\\right)^m=e^x\\)</span>.</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(x=-1\\)</span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{m\\to\\infty}\\left(1-\\frac{1}{m}\\right)^m=e^{-1}=\\frac{1}{e}\\)</span>.</span> הסדרה עם <span class=\"math math-inline\" dir=\"ltr\">\\(m=n^2\\)</span> היא תת-סדרה של זו (משפט 3.25), ולכן:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}\\left(1-\\frac{1}{n^2}\\right)^{n^2}=\\frac{1}{e}&gt;0.\\]</div>\n<p>(לחלופין, מהגדרת <span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span> וטענה 6.18 עם <span class=\"math math-inline\" dir=\"ltr\">\\(u_n=-\\frac{1}{n^2}\\to 0\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\left(1-\\frac{1}{n^2}\\right)^{-n^2}\\to e\\)</span>,</span> ובהעלאה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(-1\\)</span></span> נקבל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{e}\\)</span>.)</span></p>\n<ul><li>עבור המעריך החיצוני:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}\\frac{n^2-1}{n^3}=\\lim_{n\\to\\infty}\\left(\\frac{1}{n}-\\frac{1}{n^3}\\right)=0-0=0.\\]</div>\n<p><em>למה?</em> הביטוי הפנימי כבר סגר את הקשר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>,</span> אז המעריך שנשאר בחוץ מספר מי ניצח במרוץ: <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{n^2-1}{n^3}\\)</span> הולך <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> מה שאומר שהבסיס ניצח והחזקה נהיית מתונה לכיוון <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></p>","<p><strong>שלב 3: הסקת הגבול.</strong> הבסיס <span class=\"math math-inline\" dir=\"ltr\">\\(\\left(1-\\frac{1}{n^2}\\right)^{n^2}\\)</span> חיובי לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\ge 2\\)</span> ושואף לגבול חיובי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{e}&gt;0\\)</span>,</span> והמעריך <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{n^2-1}{n^3}\\)</span> שואף <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></span> לפי טענה 6.15 (גבול של חזקה):</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{n\\to\\infty}a_n=\\left(\\frac{1}{e}\\right)^0=1.\\]</div>\n<p><strong>התשובה הנכונה: ב</strong></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לסמן ד <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{e}\\)</span>)</span> או ג <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>)</span> כי מזהים &quot;<span class=\"math math-inline\" dir=\"ltr\">\\(\\left(1-\\frac{1}{n^2}\\right)\\)</span> עם משהו שמזכיר את <span class=\"math math-inline\" dir=\"ltr\">\\(e\\)</span>&quot; בלי לשים לב שהמעריך הוא מסדר גודל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\)</span> ולא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(n^2\\)</span>!</span></li><li>להכפיל <span class=\"math math-inline\" dir=\"ltr\">\\(\\left(\\frac{n^2-1}{n}\\right)\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> במקום <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-\\frac{1}{n^2}\\)</span>,</span></span> או לחשב <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{n^2-1}{n}\\to\\infty\\)</span> ולחשוב שהתוצאה היא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{e}\\)</span>.</span></li></ul></div></div>"}],"similar":"","mc":{"answer":"ב"}},"6":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(5 נקודות) אם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במידה שווה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> אז היא חסומה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span> א. הטענה נכונה. ב. הטענה אינה נכונה.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">על קטע פתוח וחסום <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> (באורך סופי), פונקציה שרציפה במידה שווה לא יכולה לברוח לאינסוף באף מקום בפנים וגם לא בקצוות — ולכן היא חייבת להיות חסומה.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: על קטע פתוח וחסום <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> (באורך סופי), פונקציה שרציפה במידה שווה לא יכולה לברוח לאינסוף באף מקום בפנים וגם לא בקצוות — ולכן היא חייבת להיות חסומה.</p>\n<p><strong>תמונה בראש</strong>: דמיינו כביש פתוח באורך סופי בין <span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span> <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span>,</span></span> שהנסיעה עליו רגועה (רציפה במ&quot;ש): בכל צעד של <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span> הגובה משתנה לכל היותר <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span> מכיוון שאורך הקטע <span class=\"math math-inline\" dir=\"ltr\">\\(b-a\\)</span> הוא סופי, מספיק מספר סופי של צעדים כדי לחצות את כולו מצד לצד — ולכן הגובה לעולם לא יכול להספיק לטפס לאינסוף!</p>\n<p><strong>עם מספרים</strong>: על הקטע הפתוח <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,2)\\)</span>,</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{1}{x}\\)</span> אינה חסומה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(g(0.01)=100\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(g(0.0001)=10000\\)</span>),</span> ולכן גם <em>לא יכולה</em> להיות רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,2)\\)</span>.</span></span> לעומת זאת, <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sin(5x)+0.5x\\)</span> רציפה במ&quot;ש <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,2)\\)</span>,</span></span> והגבולות שלה בקצוות <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(2\\)</span></span> סופיים (בערך <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0.46\\)</span>),</span></span> כך שהיא כלואה בגבהים סופיים.</p>\n<p>בקורס זה, הסימון <strong><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span></strong> (ללא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\pm\\infty\\)</span>)</span> מציין קטע פתוח וחסום עם קצוות ממשיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;b\\)</span>.</span> (בקטע אינסופי כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span> פונקציה כמו <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span> כן רציפה במ&quot;ש ואינה חסומה!)</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בקטע הפתוח החסום <span class=\"math math-inline\" dir=\"ltr\">\\((0,2)\\)</span> (בין הקווים האפורים <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=2\\)</span>):</span></span> בכחול הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\sin(5x)+0.5x\\)</span> שרציפה במידה שווה וחסומה לגמרי, לעומת האדומה <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\frac{1}{x}\\)</span> שאינה חסומה ליד <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> — ובהתאם לכך קופצת בחדות ליד <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> ואינה רציפה במ&quot;ש.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.2,&quot;xmax&quot;:2.3,&quot;ymin&quot;:-1.6,&quot;ymax&quot;:6}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\sin(5x)+0.5x&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;g&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;g(x)=\\\\frac{1}{x}&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;l&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=0&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;r&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=2&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: אפיון הרציפות במ\"ש בקטע פתוח חסום","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: אפיון הרציפות במ&quot;ש בקטע פתוח חסום</p><div class=\"callout-body\"><p>מה אומר משפט 5.49 על פונקציה שרציפה במ&quot;ש בקטע פתוח וחסום <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>?</span></p></div></div>"},{"title":"רמז 2: הרחבה לקטע הסגור $[a,b]$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: הרחבה לקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></p><div class=\"callout-body\"><p>אם לגבול <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to a^+}f(x)\\)</span> ולגבול <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to b^-}f(x)\\)</span> יש ערכים סופיים, אפשר להגדיר פונקציה רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> שמסכימה עם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span> איזה משפט מבטיח חסימות?</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נציג דרך קצרה באמצעות משפט 5.49 (קיום גבולות סופיים בקצוות) והרחבה רציפה לקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> יחד עם המשפט הראשון של ויירשטראס (5.35). בנוסף, נבין גם ישירות מההגדרה <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=1\\)</span></span> וחלוקת <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> למספר סופי של תתי-קטעים) מדוע <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה.</p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p>בקורס, הקטע <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> מסמל קטע פתוח וחסום <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a,b\\in\\mathbb R\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;b\\)</span>).</span></p>\n<p><strong>שלב 1: שימוש באפיון הרציפות במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span></span></strong> נתון כי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>,</span></span> ולכן היא רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span></span> (טענה 5.47). לפי משפט 5.49 (אפיון רציפות במידה שווה בקטע פתוח חסום), קיימים גבולות חד-צדדיים סופיים בקצוות:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L_a=\\lim_{x\\to a^+}f(x)\\in\\mathbb R \\quad\\text{וגם}\\quad L_b=\\lim_{x\\to b^-}f(x)\\in\\mathbb R.\\]</div>\n<p><strong>שלב 2: הרחבה רציפה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> והסקת חסימות.</strong> נגדיר פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g:[a,b]\\to\\mathbb R\\)</span> על ידי:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(x)=\\begin{cases}L_a &amp; x=a,\\\\ f(x) &amp; a&lt;x&lt;b,\\\\ L_b &amp; x=b.\\end{cases}\\]</div>\n<p>הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> רציפה בכל נקודה של <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> (שם היא שווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span>),</span></span> רציפה מימין <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to a^+}g(x)=L_a=g(a)\\)</span>)</span> ורציפה משמאל <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to b^-}g(x)=L_b=g(b)\\)</span>).</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> רציפה בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> (הגדרה 5.26). לפי המשפט הראשון של ויירשטראס (משפט 5.35), <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> ובפרט הצמצום שלה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>,</span></span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span>,</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span></span></p>\n<p><em>למה?</em> אפשר לראות את החסימות גם ישירות מהגדרת הרציפות במ&quot;ש (הגדרה 5.46) עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=1\\)</span>:</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> שכל שתי נקודות במרחק פחות <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span></span> נותנות הפרש ערכים פחות <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span> אם נחלק את <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(N\\)</span></span> תתי-קטעים שווים באורך קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span></span> (למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{b-a}{N}&lt;\\delta\\)</span>),</span> ונבחר נקודת נציג אחת <span class=\"math math-inline\" dir=\"ltr\">\\(t_k\\)</span> בכל תת-קטע, אז כל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(a,b)\\)</span> נמצא במרחק קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span></span> מאחד הנציגים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t_k\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le\\max_{1\\le k\\le N}|f(t_k)|+1\\)</span>.</span></p>\n<p><strong>התשובה הנכונה: א</strong></p></div></div>","steps":["<p>בקורס, הקטע <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> מסמל קטע פתוח וחסום <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(a,b\\in\\mathbb R\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(a&lt;b\\)</span>).</span></p>\n<p><strong>שלב 1: שימוש באפיון הרציפות במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span></span></strong> נתון כי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> רציפה במידה שווה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>,</span></span> ולכן היא רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span></span> (טענה 5.47). לפי משפט 5.49 (אפיון רציפות במידה שווה בקטע פתוח חסום), קיימים גבולות חד-צדדיים סופיים בקצוות:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[L_a=\\lim_{x\\to a^+}f(x)\\in\\mathbb R \\quad\\text{וגם}\\quad L_b=\\lim_{x\\to b^-}f(x)\\in\\mathbb R.\\]</div>","<p><strong>שלב 2: הרחבה רציפה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span></span> והסקת חסימות.</strong> נגדיר פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g:[a,b]\\to\\mathbb R\\)</span> על ידי:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[g(x)=\\begin{cases}L_a &amp; x=a,\\\\ f(x) &amp; a&lt;x&lt;b,\\\\ L_b &amp; x=b.\\end{cases}\\]</div>\n<p>הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> רציפה בכל נקודה של <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> (שם היא שווה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span>),</span></span> רציפה מימין <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(a\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to a^+}g(x)=L_a=g(a)\\)</span>)</span> ורציפה משמאל <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(b\\)</span></span> <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to b^-}g(x)=L_b=g(b)\\)</span>).</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> רציפה בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span> (הגדרה 5.26). לפי המשפט הראשון של ויירשטראס (משפט 5.35), <span class=\"math math-inline\" dir=\"ltr\">\\(g\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([a,b]\\)</span>,</span></span> ובפרט הצמצום שלה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>,</span></span> כלומר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span>,</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span>.</span></span></p>\n<p><em>למה?</em> אפשר לראות את החסימות גם ישירות מהגדרת הרציפות במ&quot;ש (הגדרה 5.46) עבור <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\varepsilon=1\\)</span>:</span> קיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\delta&gt;0\\)</span> שכל שתי נקודות במרחק פחות <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span></span> נותנות הפרש ערכים פחות <span class=\"nobr\">מ-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>.</span></span> אם נחלק את <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(N\\)</span></span> תתי-קטעים שווים באורך קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span></span> (למשל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{b-a}{N}&lt;\\delta\\)</span>),</span> ונבחר נקודת נציג אחת <span class=\"math math-inline\" dir=\"ltr\">\\(t_k\\)</span> בכל תת-קטע, אז כל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(a,b)\\)</span> נמצא במרחק קטן <span class=\"nobr\">מ-<span class=\"math math-inline\" dir=\"ltr\">\\(\\delta\\)</span></span> מאחד הנציגים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(t_k\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le\\max_{1\\le k\\le N}|f(t_k)|+1\\)</span>.</span></p>\n<p><strong>התשובה הנכונה: א</strong></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לחשוב על הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac{1}{x}\\)</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> ולטעון שהיא &quot;רציפה ולכן מפריכה&quot; — <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{x}\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>,</span></span> אך היא <em>אינה רציפה במידה שווה</em> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>!</span></span></li><li>לבלבל בין קטע פתוח חסום <span class=\"math math-inline\" dir=\"ltr\">\\((a,b)\\)</span> לקטע אינסופי כמו <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> (שם <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span> אכן רציפה במ&quot;ש ולא חסומה).</li></ul></div></div>"}],"similar":"","mc":{"answer":"א"}},"7":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(5 נקודות) תהיינה <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span></span> קבוצות חסומות של מספרים ממשיים שאינן מכילות את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span> נסמן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(C=\\left\\{\\frac{a}{b}\\mid a\\in A,\\ b\\in B\\right\\}\\)</span>.</span> אזי: א. <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sup C=\\frac{\\sup A}{\\sup B}\\)</span>.</span> ב. <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sup C=\\frac{\\sup A}{\\inf B}\\)</span>.</span> ג. <span class=\"math math-inline\" dir=\"ltr\">\\(C\\)</span> אינה בהכרח חסומה. ד. אף אחת מהטענות הנ&quot;ל אינה נכונה.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">גם אם <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> לא נמצא בתוך הקבוצה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span>,</span> איברי <span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span> יכולים להתקרב אליו עד אין סוף — ואז חילוק בהם מעיף את קבוצת המנות <span class=\"math math-inline\" dir=\"ltr\">\\(C\\)</span> לאינסוף.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: גם אם <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> לא נמצא בתוך הקבוצה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span>,</span> איברי <span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span> יכולים להתקרב אליו עד אין סוף — ואז חילוק בהם מעיף את קבוצת המנות <span class=\"math math-inline\" dir=\"ltr\">\\(C\\)</span> לאינסוף.</p>\n<p><strong>תמונה בראש</strong>: תחשבו שבקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> יש את המספר <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span> והקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span> מורכבת מכל השברים <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{2}, \\frac{1}{3}, \\frac{1}{4}, \\dots\\)</span> כל המספרים <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span></span> חיוביים ונשארים מתחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> (אז <span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span> חסומה ולא מכילה את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>).</span> אבל כשמחלקים <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> במספרים האלה, מקבלים <span class=\"math math-inline\" dir=\"ltr\">\\(2, 3, 4, \\dots\\)</span> — שגדלים בלי תקרה!</p>\n<p><strong>עם מספרים</strong>: ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(A=\\{1\\}\\)</span> (חסומה, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\notin A\\)</span>)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(B=\\left\\{\\frac{1}{n} : n\\in\\mathbb N\\right\\}=\\{1,\\frac{1}{2},\\frac{1}{3},\\dots\\}\\)</span></span> (חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span></span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\notin B\\)</span>).</span></span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(C=\\{n : n\\in\\mathbb N\\}=\\mathbb N\\)</span>,</span> שאינה חסומה מלעיל כלל! (ולכן לפי משפט 3.6 גם אין <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(C\\)</span></span> סופרמום, מה שפוסל מראש גם את א ו-ב.)</p>\n<p><strong>קבוצה חסומה שאינה מכילה את <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></strong> עדיין יכולה להכיל מספרים קרובים כרצוננו <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> (להצטבר סביב <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>).</span> חלוקה במספרים שקרובים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> מייצרת גדלים שרירותיים.</p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>בכחול העקומה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\frac{1}{x}\\)</span>.</span> הנקודות האדומות מראות את <span class=\"math math-inline\" dir=\"ltr\">\\((b, \\frac{1}{b})\\)</span> עבור <span class=\"math math-inline\" dir=\"ltr\">\\(b\\in B=\\{1,\\frac{1}{2},\\frac{1}{4},\\frac{1}{5},\\frac{1}{8}\\}\\)</span> (<span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(A=\\{1\\}\\)</span>):</span></span> הקלטים <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span></span> נשארים כולם בקטע החסום <span class=\"math math-inline\" dir=\"ltr\">\\((0,1]\\)</span> ולא נוגעים <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>,</span></span> אבל התוצאות <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{b}\\in C\\)</span> מטפסות למעלה בלי סוף.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.1,&quot;xmax&quot;:1.2,&quot;ymin&quot;:-0.5,&quot;ymax&quot;:9.5}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=\\\\frac{1}{x}&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;p1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(1,1)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;p2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0.5,2)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;p3&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0.25,4)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;p4&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0.2,5)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;p5&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0.125,8)&quot;,&quot;color&quot;:&quot;#c74440&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: למה תנאי \"$0\\notin B$\" לא עוזר נגד התקרבות ל-$0$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: למה תנאי &quot;<span class=\"math math-inline\" dir=\"ltr\">\\(0\\notin B\\)</span>&quot; לא עוזר נגד התקרבות <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span></p><div class=\"callout-body\"><p>האם חסם מלרע חיובי של <span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span> הוא תנאי הכרחי כאן, או <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span></span> יכולה להתקרב <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> (כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\left\\{\\frac{1}{n}\\right\\}\\)</span>)?</span></p></div></div>"},{"title":"רמז 2: בנו דוגמה נגדית מפורשת","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: בנו דוגמה נגדית מפורשת</p><div class=\"callout-body\"><p>בחרו <span class=\"math math-inline\" dir=\"ltr\">\\(A=\\{1\\}\\)</span> וקבוצה חסומה <span class=\"math math-inline\" dir=\"ltr\">\\(B\\subset(0,1]\\)</span> שאינה מכילה את <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> אבל מתקרבת אליו. מה תהיה הקבוצה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(C\\)</span>?</span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נראה בדוגמה מפורשת <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(A=\\{1\\}\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(B=\\{\\frac{1}{n}:n\\in\\mathbb N\\}\\)</span>)</span> כי <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span></span> מקיימות את כל תנאי השאלה, ובכל זאת <span class=\"math math-inline\" dir=\"ltr\">\\(C=\\mathbb N\\)</span> אינה חסומה מלעיל (ולכן א ו-ב אינן נכונות — למעשה <span class=\"math math-inline\" dir=\"ltr\">\\(\\sup C\\)</span> כלל אינו קיים במקרה זה לפי משפט 3.6, ואפילו <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(C\\)</span></span> חסומה, א ו-ב שגויות גם בגלל סימנים/מכנה גדול יותר). מכאן טענה ג נכונה.</p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: בניית דוגמה שבה <span class=\"math math-inline\" dir=\"ltr\">\\(C\\)</span> אינה חסומה.</strong> נבחר:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[A=\\{1\\}, \\qquad B=\\left\\{\\frac{1}{n}\\mid n\\in\\mathbb N\\right\\}.\\]</div>\n<p>נבדוק את כל תנאי השאלה:</p>\n<ul><li>הקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> חסומה (<span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,1]\\)</span>)</span></span> ואינה מכילה את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></li><li>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;\\frac{1}{n}\\le 1\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span> חסומה ואינה מכילה את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></li></ul>\n<p>כעת נחשב את קבוצת המנות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(C\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[C=\\left\\{\\frac{1}{1/n}\\mid n\\in\\mathbb N\\right\\}=\\mathbb N=\\{1,2,3,\\dots\\}.\\]</div>\n<p>כיוון שקבוצת המספרים הטבעיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb N\\)</span> אינה חסומה מלעיל, הקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(C\\)</span> אינה חסומה. לכן טענה ג (&quot;<span class=\"math math-inline\" dir=\"ltr\">\\(C\\)</span> אינה בהכרח חסומה&quot;) היא <strong>נכונה</strong>.</p>\n<p><strong>שלב 2: וידוא שטענות א ו-ב אינן נכונות (וגם ד נפסלת).</strong> בדוגמה שבשלב 1, <span class=\"math math-inline\" dir=\"ltr\">\\(C\\)</span> אינה חסומה מלעיל, ולכן לפי אקסיומת השלמות (משפט 3.6) כלל אין לה סופרמום (וכמובן שנוסחה א נותנת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{1}=1\\)</span> ונוסחה ב אפילו מחלקת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\inf B=0\\)</span>!).</span></span> (אגב, גם אם <span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span> מורחקת מאפס: עבור <span class=\"math math-inline\" dir=\"ltr\">\\(A=[-2,-1]\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(B=[1,2]\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sup A=-1, \\sup B=2, \\inf B=1\\)</span>,</span> אבל הערכים של <span class=\"math math-inline\" dir=\"ltr\">\\(C\\)</span> הם <span class=\"math math-inline\" dir=\"ltr\">\\([-2,-\\frac{1}{2}]\\)</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sup C=-\\frac{1}{2}\\)</span>,</span> שאינו שווה לא <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sup A}{\\sup B}\\)</span></span> ולא <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sup A}{\\inf B}\\)</span>!)</span></span></p>\n<p><em>למה?</em> התנאי &quot;<span class=\"math math-inline\" dir=\"ltr\">\\(0\\notin B\\)</span>&quot; מונע רק חלוקה באפס ממש, אך אינו מרחיק את <span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span> מאפס; מותר לאיברי <span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span> לשאוף לאפס (כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\inf B=0\\)</span></span> או <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> בין גבולות הקבוצה), ואז המנות מתפוצצות.</p>\n<p><strong>התשובה הנכונה: ג</strong></p></div></div>","steps":["<p><strong>שלב 1: בניית דוגמה שבה <span class=\"math math-inline\" dir=\"ltr\">\\(C\\)</span> אינה חסומה.</strong> נבחר:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[A=\\{1\\}, \\qquad B=\\left\\{\\frac{1}{n}\\mid n\\in\\mathbb N\\right\\}.\\]</div>\n<p>נבדוק את כל תנאי השאלה:</p>\n<ul><li>הקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(A\\)</span> חסומה (<span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([1,1]\\)</span>)</span></span> ואינה מכילה את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></li><li>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(n\\in\\mathbb N\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0&lt;\\frac{1}{n}\\le 1\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span> חסומה ואינה מכילה את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span>.</span></li></ul>\n<p>כעת נחשב את קבוצת המנות <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(C\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[C=\\left\\{\\frac{1}{1/n}\\mid n\\in\\mathbb N\\right\\}=\\mathbb N=\\{1,2,3,\\dots\\}.\\]</div>\n<p>כיוון שקבוצת המספרים הטבעיים <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb N\\)</span> אינה חסומה מלעיל, הקבוצה <span class=\"math math-inline\" dir=\"ltr\">\\(C\\)</span> אינה חסומה. לכן טענה ג (&quot;<span class=\"math math-inline\" dir=\"ltr\">\\(C\\)</span> אינה בהכרח חסומה&quot;) היא <strong>נכונה</strong>.</p>","<p><strong>שלב 2: וידוא שטענות א ו-ב אינן נכונות (וגם ד נפסלת).</strong> בדוגמה שבשלב 1, <span class=\"math math-inline\" dir=\"ltr\">\\(C\\)</span> אינה חסומה מלעיל, ולכן לפי אקסיומת השלמות (משפט 3.6) כלל אין לה סופרמום (וכמובן שנוסחה א נותנת <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{1}=1\\)</span> ונוסחה ב אפילו מחלקת <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\inf B=0\\)</span>!).</span></span> (אגב, גם אם <span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span> מורחקת מאפס: עבור <span class=\"math math-inline\" dir=\"ltr\">\\(A=[-2,-1]\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(B=[1,2]\\)</span></span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sup A=-1, \\sup B=2, \\inf B=1\\)</span>,</span> אבל הערכים של <span class=\"math math-inline\" dir=\"ltr\">\\(C\\)</span> הם <span class=\"math math-inline\" dir=\"ltr\">\\([-2,-\\frac{1}{2}]\\)</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sup C=-\\frac{1}{2}\\)</span>,</span> שאינו שווה לא <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sup A}{\\sup B}\\)</span></span> ולא <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sup A}{\\inf B}\\)</span>!)</span></span></p>\n<p><em>למה?</em> התנאי &quot;<span class=\"math math-inline\" dir=\"ltr\">\\(0\\notin B\\)</span>&quot; מונע רק חלוקה באפס ממש, אך אינו מרחיק את <span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span> מאפס; מותר לאיברי <span class=\"math math-inline\" dir=\"ltr\">\\(B\\)</span> לשאוף לאפס (כך <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\inf B=0\\)</span></span> או <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> בין גבולות הקבוצה), ואז המנות מתפוצצות.</p>\n<p><strong>התשובה הנכונה: ג</strong></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>להתפתות ולחשוב שאם <span class=\"math math-inline\" dir=\"ltr\">\\(A,B\\)</span> חסומות אז &quot;חלקי&quot; נשאר חסום ולסמן ב <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\sup A}{\\inf B}\\)</span>)</span> — שוכחים <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\inf B\\)</span></span> יכול להיות <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> גם <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(0\\notin B\\)</span>,</span></span> וגם כשהמכנה חיובי וגדול מאפס צריך לבדוק את סימן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\sup A\\)</span>.</span></li><li>לכתוב בדוגמה שבשלב 1 ש-&quot;<span class=\"math math-inline\" dir=\"ltr\">\\(\\sup C=\\infty\\)</span>&quot;: בקורס הזה סופרמום מוגדר רק לקבוצה לא ריקה וחסומה מלעיל (משפט 3.6); עבור <span class=\"math math-inline\" dir=\"ltr\">\\(\\mathbb N\\)</span> אומרים שאינה חסומה מלעיל ולכן אין לה סופרמום.</li></ul></div></div>"}],"similar":"","mc":{"answer":"ג"}},"8":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(5 נקודות) אם <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> ואם <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)&gt;0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span>,</span> אז <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}f(x)=\\infty\\)</span>.</span> א. הטענה נכונה. ב. הטענה אינה נכונה.</p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">פונקציה יכולה לעלות כל הזמן <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f'&gt;0\\)</span>)</span> ועדיין להתמתן ולהתקרב מלמטה לתקרה אופקית (אסימפטוטה) בלי לעבור אותה לעולם.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: פונקציה יכולה לעלות כל הזמן <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f'&gt;0\\)</span>)</span> ועדיין להתמתן ולהתקרב מלמטה לתקרה אופקית (אסימפטוטה) בלי לעבור אותה לעולם.</p>\n<p><strong>תמונה בראש</strong>: תחשבו על צעדן שצועד בכל יום חצי מהמרחק שנשאר לו לקיר: הוא תמיד מתקדם קדימה (המהירות שלו תמיד חיובית, <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)&gt;0\\)</span>),</span> אבל הצעדים שלו הולכים וקטנים כל כך מהר שהוא לעולם לא עובר את הקיר — הוא פשוט מתקרב אליו בגבול סופי.</p>\n<p><strong>עם מספרים</strong>: נבחן את <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=-\\frac{1}{x}\\)</span> על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>:</span> הנגזרת היא <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=\\frac{1}{x^2}&gt;0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> ובכל זאת <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=10\\)</span></span> הגובה הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-0.1\\)</span>,</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=100\\)</span></span> הוא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(-0.01\\)</span>,</span> <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(x=1000\\)</span></span> הוא <span class=\"math math-inline\" dir=\"ltr\">\\(-0.001\\)</span> — הגבול <span class=\"nobr\">כש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\to\\infty\\)</span></span> הוא <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> ולא <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span>!</span> דוגמאות פשוטות נוספות הן <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=1-e^{-x}\\)</span> (שגבולה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=\\arctan x\\)</span></span> (שגבולה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{\\pi}{2}\\)</span>).</span></p>\n<p><strong>נגזרת חיובית</strong> מבטיחה עלייה ממש, אך כדי להבטיח שהגובה יטפס עד <span class=\"math math-inline\" dir=\"ltr\">\\(\\infty\\)</span> לא די <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)&gt;0\\)</span>:</span></span> צריך למשל שלנגזרת יהיה חסם תחתון חיובי קבוע כמו <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\ge c&gt;0\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>שתי דוגמאות נגדיות על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>:</span> באדום <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=-\\frac{1}{x}\\)</span> (שנגזרתה <span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{x^2}&gt;0\\)</span> אבל נבלמת באסימפטוטה הכחולה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=0\\)</span>)</span> ובכתום <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=1-e^{-x}\\)</span> (שנגזרתה <span class=\"math math-inline\" dir=\"ltr\">\\(e^{-x}&gt;0\\)</span> אבל נבלמת באסימפטוטה הירוקה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(y=1\\)</span>).</span> שתיהן עולות כל הזמן אך לא שואפות לאינסוף.</p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:0,&quot;xmax&quot;:8,&quot;ymin&quot;:-2,&quot;ymax&quot;:1.4}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=-\\\\frac{1}{x}&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;a1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=0&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;g&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;g(x)=1-e^{-x}&quot;,&quot;color&quot;:&quot;#fa7e19&quot;},{&quot;id&quot;:&quot;a2&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;y=1&quot;,&quot;color&quot;:&quot;#388c46&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: חפשו פונקציה עולה עם אסימפטוטה אופקית ב-$+\\infty$","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: חפשו פונקציה עולה עם אסימפטוטה אופקית <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(+\\infty\\)</span></span></p><div class=\"callout-body\"><p>אילו פונקציות מוכרות גזירות <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>,</span></span> תמיד עולות ממש <span class=\"nobr\">(<span class=\"math math-inline\" dir=\"ltr\">\\(f'&gt;0\\)</span>),</span> ועדיין מתכנסות לגבול סופי <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to\\infty\\)</span>?</span></span></p></div></div>"},{"title":"רמז 2: דוגמאות קלאסיות פשוטות","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: דוגמאות קלאסיות פשוטות</p><div class=\"callout-body\"><p>בדקו את <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=-\\frac{1}{x}\\)</span> (או <span class=\"math math-inline\" dir=\"ltr\">\\(1-e^{-x}\\)</span> או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span>):</span> מה הסימן של <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\)</span> ומה הגבול <span class=\"nobr\">כש-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\to\\infty\\)</span>?</span></span></p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נפריך את הטענה בעזרת דוגמה נגדית מפורשת: <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=-\\frac{1}{x}\\)</span> (או <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\arctan x\\)</span>),</span> נוודא שהיא גזירה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span></span> ומתקיים <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)&gt;0\\)</span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x&gt;0\\)</span>,</span> אך <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}f(x)=0\\ne\\infty\\)</span>.</span></p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: בחירת דוגמה נגדית ובדיקת התנאים.</strong> נגדיר <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span></span> את הפונקציה:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=-\\frac{1}{x}.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span>,</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> (משפט 7.19), ונגזרתה היא:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x)=\\frac{1}{x^2}.\\]</div>\n<p>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2&gt;0\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=\\frac{1}{x^2}&gt;0\\)</span>.</span> מכאן שכל תנאי הטענה מתקיימים.</p>\n<p><strong>שלב 2: חישוב הגבול באינסוף והפרכה.</strong> מאידך, מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to\\infty}f(x)=\\lim_{x\\to\\infty}\\left(-\\frac{1}{x}\\right)=0\\ne\\infty.\\]</div>\n<p>(באופן דומה, גם <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\arctan x\\)</span> מקיימת <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)=\\frac{1}{1+x^2}&gt;0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}g(x)=\\frac{\\pi}{2}\\)</span>.)</span></span> לכן הטענה אינה נכונה.</p>\n<p><em>למה?</em> משפט 3.16 מהסדרות (פונקציה/סדרה מונוטונית עולה וחסומה מלעיל מתכנסת לגבול סופי) עובד כאן בדיוק: עלייה ממש מאפשרת לפונקציה להתקרב לאסימפטוטה אופקית, כל עוד השיפוע קטן בקצב שמסתכם למרחק סופי.</p>\n<p><strong>התשובה הנכונה: ב</strong></p></div></div>","steps":["<p><strong>שלב 1: בחירת דוגמה נגדית ובדיקת התנאים.</strong> נגדיר <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span></span> את הפונקציה:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f(x)=-\\frac{1}{x}.\\]</div>\n<p>כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(x\\ne 0\\)</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span>,</span> הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> גזירה בכל <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span> (משפט 7.19), ונגזרתה היא:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[f'(x)=\\frac{1}{x^2}.\\]</div>\n<p>לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,\\infty)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x^2&gt;0\\)</span>,</span> ולכן <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)=\\frac{1}{x^2}&gt;0\\)</span>.</span> מכאן שכל תנאי הטענה מתקיימים.</p>","<p><strong>שלב 2: חישוב הגבול באינסוף והפרכה.</strong> מאידך, מתקיים:</p>\n<div class=\"math math-display\" dir=\"ltr\">\\[\\lim_{x\\to\\infty}f(x)=\\lim_{x\\to\\infty}\\left(-\\frac{1}{x}\\right)=0\\ne\\infty.\\]</div>\n<p>(באופן דומה, גם <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=\\arctan x\\)</span> מקיימת <span class=\"math math-inline\" dir=\"ltr\">\\(g'(x)=\\frac{1}{1+x^2}&gt;0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to\\infty}g(x)=\\frac{\\pi}{2}\\)</span>.)</span></span> לכן הטענה אינה נכונה.</p>\n<p><em>למה?</em> משפט 3.16 מהסדרות (פונקציה/סדרה מונוטונית עולה וחסומה מלעיל מתכנסת לגבול סופי) עובד כאן בדיוק: עלייה ממש מאפשרת לפונקציה להתקרב לאסימפטוטה אופקית, כל עוד השיפוע קטן בקצב שמסתכם למרחק סופי.</p>\n<p><strong>התשובה הנכונה: ב</strong></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לחשוב ש&quot;<span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)&gt;0\\)</span> בכל <span class=\"math math-inline\" dir=\"ltr\">\\((0,\\infty)\\)</span>&quot; שקול לתנאי &quot;<span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\ge c&gt;0\\)</span>&quot;: בתנאי החזק יותר <span class=\"math math-inline\" dir=\"ltr\">\\(f'(x)\\ge c&gt;0\\)</span> אכן מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)\\ge f(1)+c(x-1)\\to\\infty\\)</span>,</span> אבל בלי החסם החיובי מלרע על <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f'\\)</span>,</span> הנגזרת יכולה לשאוף <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> ולעצור את העלייה.</li></ul></div></div>"}],"similar":"<p><strong>שאלות דומות</strong>: <a href=\"#/exams/30/q4\">2024א · מועד 88, שאלה 4</a> · <a href=\"#/exams/43/q5\">2026ב · מועד 88, שאלה 5</a> · <a href=\"#/exams/45/q9\">2026ג · מועד 83, שאלה 9</a></p>","mc":{"answer":"ב"}},"9":{"question":"<div class=\"callout callout-question\"><p class=\"callout-title\">השאלה</p><div class=\"callout-body\"><p>(5 נקודות) תהי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> פונקציה רציפה בקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span> ומקיימת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}f(x)=0\\)</span>,</span> <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 1^-}f(x)=1\\)</span>.</span> אז: א. הטווח של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> הוא הקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span> ב. <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span> ג. <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> מונוטונית עולה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span> ד. <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> יש מקסימום בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span></p></div></div>","parts":[{"label":"","simple":"<details class=\"callout callout-simple\" open><summary class=\"callout-title\"><span class=\"callout-title-text\">במילים פשוטות</span><span class=\"callout-teaser\">כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה בין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> ויש לה גבולות סופיים משני הקצוות, אפשר לסתום את שני החורים בקצוות ולקבל פונקציה רציפה על <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> — ולפי ויירשטראס הראשון היא חייבת להיות חסומה.</span></summary><div class=\"callout-body\"><p><strong>בשורה אחת</strong>: כיוון <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> רציפה בין <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> ויש לה גבולות סופיים משני הקצוות, אפשר לסתום את שני החורים בקצוות ולקבל פונקציה רציפה על <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> — ולפי ויירשטראס הראשון היא חייבת להיות חסומה.</p>\n<p><strong>תמונה בראש</strong>: תחשבו על גשר שתלוי בין שתי נקודות עגינה ידועות: גובה <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> בקצה השמאלי וגובה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> בקצה הימני. הגשר לא חייב לעלות ישר בין העוגנים — הוא יכול להתנדנד למעלה מעבר <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> ולמטה מתחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> (שולל טווח <span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span> ושולל מונוטוניות), והוא גם יכול להיות קו ישר אלכסוני בלי אף פסגה (שולל מקסימום). אבל הוא לעולם לא יכול לברוח לאינסוף, כי הוא רציף ומעוגן משני צדדיו!</p>\n<p><strong>עם מספרים</strong>:</p>\n<ul><li>הקו הישר <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=x\\)</span> רציף <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> עם גבולות <span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span>,</span></span> ואין לו מקסימום <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> (כי הערכים מתקרבים <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> ולא מגיעים אליו).</li><li>הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(h(x)=x+\\sin(2\\pi x)\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> עם גבולות <span class=\"math math-inline\" dir=\"ltr\">\\(0+0=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(1+0=1\\)</span>,</span></span> אבל <span class=\"math math-inline\" dir=\"ltr\">\\(h(\\frac{1}{4})=0.25+1=1.25&gt;1\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(h(\\frac{3}{4})=0.75-1=-0.25&lt;0\\)</span></span> — כך שהיא גם יוצאת מתוך <span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span> וגם יורדת באמצע!</li></ul>\n<p><strong>חסומה בקטע</strong> פירושו שיש מספר <span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\)</span> בקטע מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|\\le M\\)</span>.</span></p></div></details>","graphs":[{"title":"רואים את זה בגרף","html":"<details class=\"callout callout-graph\"><summary class=\"callout-title\"><span class=\"callout-title-text\">רואים את זה בגרף</span></summary><div class=\"callout-body\"><p>באדום <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x+\\sin(2\\pi x)\\)</span> (מקיימת את שני הגבולות בקצוות, אך מטפסת עד <span class=\"math math-inline\" dir=\"ltr\">\\(1.25\\)</span> ויורדת עד <span class=\"math math-inline\" dir=\"ltr\">\\(-0.25\\)</span> — כך שהיא מפריכה הן את א והן את ג), ובכחול <span class=\"math math-inline\" dir=\"ltr\">\\(g(x)=x\\)</span> (חסרת מקסימום בקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span> — מפריכה את ד). שתיהן חסומות היטב בין הקווים האפורים <span class=\"math math-inline\" dir=\"ltr\">\\(x=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x=1\\)</span>.</span></span></p>\n<figure class=\"demo\" data-desmos=\"{&quot;graph&quot;:{&quot;viewport&quot;:{&quot;xmin&quot;:-0.15,&quot;xmax&quot;:1.15,&quot;ymin&quot;:-0.45,&quot;ymax&quot;:1.45}},&quot;expressions&quot;:{&quot;list&quot;:[{&quot;id&quot;:&quot;f&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;f(x)=x+\\\\sin(2\\\\pi x)&quot;,&quot;color&quot;:&quot;#c74440&quot;},{&quot;id&quot;:&quot;g&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;g(x)=x&quot;,&quot;color&quot;:&quot;#2d70b3&quot;},{&quot;id&quot;:&quot;l&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=0&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;r&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;x=1&quot;,&quot;color&quot;:&quot;#666666&quot;,&quot;lineStyle&quot;:&quot;DASHED&quot;},{&quot;id&quot;:&quot;p0&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(0,0)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;pointStyle&quot;:&quot;OPEN&quot;,&quot;showLabel&quot;:true},{&quot;id&quot;:&quot;p1&quot;,&quot;type&quot;:&quot;expression&quot;,&quot;latex&quot;:&quot;(1,1)&quot;,&quot;color&quot;:&quot;#2d70b3&quot;,&quot;pointStyle&quot;:&quot;OPEN&quot;,&quot;showLabel&quot;:true}]}}\"><noscript><p>הגרף דורש JavaScript.</p></noscript></figure></div></details>"}],"hints":[{"title":"רמז 1: הוכחת הנכונות (אפשרות ב)","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 1: הוכחת הנכונות (אפשרות ב)</p><div class=\"callout-body\"><p>הגדירו פונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(F\\)</span> על הקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> על ידי <span class=\"math math-inline\" dir=\"ltr\">\\(F(0)=0, F(1)=1\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(F(x)=f(x)\\)</span></span> בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span> מדוע <span class=\"math math-inline\" dir=\"ltr\">\\(F\\)</span> רציפה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>?</span></span></p></div></div>"},{"title":"רמז 2: שימוש במשפט ויירשטראס הראשון","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 2: שימוש במשפט ויירשטראס הראשון</p><div class=\"callout-body\"><p>מה מבטיח משפט 5.35 על הפונקציה הרציפה <span class=\"math math-inline\" dir=\"ltr\">\\(F\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span></span> ומה נובע מכך לגבי <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>?</span></span></p></div></div>"},{"title":"רמז 3: הפרכת שלוש האפשרויות האחרות","html":"<div class=\"callout callout-hint\"><p class=\"callout-title\">רמז 3: הפרכת שלוש האפשרויות האחרות</p><div class=\"callout-body\"><p>איזו פונקציה פשוטה מפריכה את ד (קיום מקסימום)? ואיזו פונקציה מגביהה מעל <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> ויורדת באמצע כדי להפריך את א ואת ג?</p></div></div>"}],"plan":"<div class=\"callout callout-plan\"><p class=\"callout-title\">התוכנית בשלוש שורות</p><div class=\"callout-body\"><p>נוכיח את טענה ב באמצעות הרחבה רציפה של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> לקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> והפעלת המשפט הראשון של ויירשטראס (5.35). לאחר מכן נפריך את א, ג ו-ד בדוגמאות נגדיות מפורשות.</p></div></div>","solution":"<div class=\"callout callout-solution\"><p class=\"callout-title\">פתרון מלא</p><div class=\"callout-body\"><p><strong>שלב 1: הוכחה שטענה ב נכונה.</strong> נגדיר פונקציה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(F:[0,1]\\to\\mathbb R\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[F(x)=\\begin{cases}0 &amp; x=0,\\\\ f(x) &amp; 0&lt;x&lt;1,\\\\ 1 &amp; x=1.\\end{cases}\\]</div>\n<p>הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(F\\)</span> רציפה בכל נקודה בקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span> כי היא שווה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> בסביבתה, רציפה מימין <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}F(x)=\\lim_{x\\to 0^+}f(x)=0=F(0)\\)</span>,</span> ורציפה משמאל <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 1^-}F(x)=\\lim_{x\\to 1^-}f(x)=1=F(1)\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(F\\)</span> רציפה בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> (הגדרה 5.26). לפי המשפט הראשון של ויירשטראס (משפט 5.35), <span class=\"math math-inline\" dir=\"ltr\">\\(F\\)</span> חסומה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> כלומר קיים <span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[0,1]\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|F(x)|\\le M\\)</span>.</span> בפרט, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|=|F(x)|\\le M\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span></span></p>\n<p><em>למה?</em> משפט ויירשטראס דורש קטע <em>סגור</em>. העובדה שקיימים גבולות סופיים בקצוות היא שמרשה לנו &quot;לסגור את הפתחים&quot; עם <span class=\"math math-inline\" dir=\"ltr\">\\(F(0)=0\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(F(1)=1\\)</span></span> בלי ליצור קפיצה!</p>\n<p><strong>שלב 2: הפרכת טענות א, ג ו-ד.</strong></p>\n<ul><li><strong>הפרכת ד</strong>: ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span></span> היא רציפה ומקיימת <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}f(x)=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 1^-}f(x)=1\\)</span>.</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span>,</span> הנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(y=\\frac{x+1}{2}\\)</span> שייכת אף היא <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> ומקיימת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(y)=\\frac{x+1}{2}&gt;x=f(x)\\)</span>,</span> ולכן <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> אין מקסימום <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span></span></li><li><strong>הפרכת א ו-ג</strong>: ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x+\\sin(2\\pi x)\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span></span> היא רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> ומקיימת <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}f(x)=0+\\sin 0=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 1^-}f(x)=1+\\sin(2\\pi)=1\\)</span>.</span></span> אולם:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[f\\left(\\frac{1}{4}\\right)=\\frac{1}{4}+\\sin\\left(\\frac{\\pi}{2}\\right)=1.25&gt;1, \\qquad f\\left(\\frac{3}{4}\\right)=\\frac{3}{4}+\\sin\\left(\\frac{3\\pi}{2}\\right)=-0.25&lt;0.\\]</div>\n<p>מכאן שהטווח של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> כולל מספרים מחוץ <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> (שולל את א), וגם <span class=\"math math-inline\" dir=\"ltr\">\\(f(\\frac{1}{4})&gt;f(\\frac{3}{4})\\)</span> אף <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{4}&lt;\\frac{3}{4}\\)</span></span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה מונוטונית עולה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> (שולל את ג).</p>\n<p><strong>התשובה הנכונה: ב</strong></p></div></div>","steps":["<p><strong>שלב 1: הוכחה שטענה ב נכונה.</strong> נגדיר פונקציה <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(F:[0,1]\\to\\mathbb R\\)</span>:</span></p>\n<div class=\"math math-display\" dir=\"ltr\">\\[F(x)=\\begin{cases}0 &amp; x=0,\\\\ f(x) &amp; 0&lt;x&lt;1,\\\\ 1 &amp; x=1.\\end{cases}\\]</div>\n<p>הפונקציה <span class=\"math math-inline\" dir=\"ltr\">\\(F\\)</span> רציפה בכל נקודה בקטע הפתוח <span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span> כי היא שווה <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> בסביבתה, רציפה מימין <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}F(x)=\\lim_{x\\to 0^+}f(x)=0=F(0)\\)</span>,</span> ורציפה משמאל <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span></span> כי <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 1^-}F(x)=\\lim_{x\\to 1^-}f(x)=1=F(1)\\)</span>.</span> לכן <span class=\"math math-inline\" dir=\"ltr\">\\(F\\)</span> רציפה בקטע הסגור <span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span> (הגדרה 5.26). לפי המשפט הראשון של ויירשטראס (משפט 5.35), <span class=\"math math-inline\" dir=\"ltr\">\\(F\\)</span> חסומה בקטע <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span> כלומר קיים <span class=\"math math-inline\" dir=\"ltr\">\\(M&gt;0\\)</span> כך שלכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in[0,1]\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|F(x)|\\le M\\)</span>.</span> בפרט, לכל <span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span> מתקיים <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(|f(x)|=|F(x)|\\le M\\)</span>,</span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> חסומה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span></span></p>\n<p><em>למה?</em> משפט ויירשטראס דורש קטע <em>סגור</em>. העובדה שקיימים גבולות סופיים בקצוות היא שמרשה לנו &quot;לסגור את הפתחים&quot; עם <span class=\"math math-inline\" dir=\"ltr\">\\(F(0)=0\\)</span> <span class=\"nobr\">ו-<span class=\"math math-inline\" dir=\"ltr\">\\(F(1)=1\\)</span></span> בלי ליצור קפיצה!</p>","<p><strong>שלב 2: הפרכת טענות א, ג ו-ד.</strong></p>\n<ul><li><strong>הפרכת ד</strong>: ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span></span> היא רציפה ומקיימת <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}f(x)=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 1^-}f(x)=1\\)</span>.</span></span> לכל <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(x\\in(0,1)\\)</span>,</span> הנקודה <span class=\"math math-inline\" dir=\"ltr\">\\(y=\\frac{x+1}{2}\\)</span> שייכת אף היא <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> ומקיימת <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(y)=\\frac{x+1}{2}&gt;x=f(x)\\)</span>,</span> ולכן <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span></span> אין מקסימום <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span></span></li><li><strong>הפרכת א ו-ג</strong>: ניקח <span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x+\\sin(2\\pi x)\\)</span> <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>.</span></span> היא רציפה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> ומקיימת <span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 0^+}f(x)=0+\\sin 0=0\\)</span> <span class=\"nobr\">ו-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(\\lim_{x\\to 1^-}f(x)=1+\\sin(2\\pi)=1\\)</span>.</span></span> אולם:</li></ul>\n<div class=\"math math-display\" dir=\"ltr\">\\[f\\left(\\frac{1}{4}\\right)=\\frac{1}{4}+\\sin\\left(\\frac{\\pi}{2}\\right)=1.25&gt;1, \\qquad f\\left(\\frac{3}{4}\\right)=\\frac{3}{4}+\\sin\\left(\\frac{3\\pi}{2}\\right)=-0.25&lt;0.\\]</div>\n<p>מכאן שהטווח של <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> כולל מספרים מחוץ <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> (שולל את א), וגם <span class=\"math math-inline\" dir=\"ltr\">\\(f(\\frac{1}{4})&gt;f(\\frac{3}{4})\\)</span> אף <span class=\"nobr\">ש-<span class=\"math math-inline\" dir=\"ltr\">\\(\\frac{1}{4}&lt;\\frac{3}{4}\\)</span></span> ולכן <span class=\"math math-inline\" dir=\"ltr\">\\(f\\)</span> אינה מונוטונית עולה <span class=\"nobr\">ב-<span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span></span> (שולל את ג).</p>\n<p><strong>התשובה הנכונה: ב</strong></p>"],"mistakes":"<div class=\"callout callout-mistake\"><p class=\"callout-title\">טעויות נפוצות</p><div class=\"callout-body\"><ul><li>לסמן א כי חושבים בטעות על משפט ערך הביניים (5.29) בכיוון ההפוך: משפט ערך הביניים מבטיח שהטווח <em>מכיל</em> את <span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>,</span> אבל הפונקציה חופשייה לטפס מעל <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> ולרדת מתחת <span class=\"nobr\">ל-<span class=\"math math-inline\" dir=\"ltr\">\\(0\\)</span></span> בתוך הקטע!</li><li>לנסות להפעיל את ויירשטראס השני (5.37) על <span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span> ולסמן ד — הקטע <span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span> אינו סגור! (בהרחבה <span class=\"nobr\">ל-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\([0,1]\\)</span>,</span></span> המקסימום יכול ליפול דווקא בנקודת הקצה <span class=\"math math-inline\" dir=\"ltr\">\\(1\\)</span> שאינה <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\((0,1)\\)</span>,</span></span> כמו <span class=\"nobr\">ב-<span class=\"nobr\"><span class=\"math math-inline\" dir=\"ltr\">\\(f(x)=x\\)</span>.)</span></span></li></ul></div></div>"}],"similar":"<p><strong>שאלות דומות</strong>: <a href=\"#/exams/44/q5\">2026ב · מועד 97, שאלה 5</a></p>","mc":{"answer":"ב"}}};
